function miniTask(t){return `<div class="mini-task ${t.status==='Done'?'done':''}"><button class="taskcheck ${t.status==='Done'?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="${t.status==='Done'?'Reopen':'Complete'} ${esc(t.title)}">${t.status==='Done'?icon('check'):''}</button><button class="tasktext" data-action="edit" data-id="${t.id}"><strong>${esc(t.title)}</strong><span>${esc(t.data.project||t.tags[0]||'My life')} · ${t.minutes||15} min ${t.date?'· '+esc(t.date):''}</span></button><button class="pin ${t.favorite?'pinned':''}" data-action="favorite" data-id="${t.id}" aria-label="${t.favorite?'Unpin':'Pin'} priority">${icon('star')}</button></div>`}
