function card(r){const def=types[r.type]||types.note;let extra='';if(r.type==='account')extra=`<strong class=amount>${dollars(r.data.balance||0)}</strong><small>${esc(r.data.kind||'Account')} · checked ${esc(r.data.asOf||r.date||'unknown date')} · manual snapshot</small>`;if(r.type==='plannedIncome')extra=`<strong class=amount>${dollars(r.data.amount||0)}</strong><small>${esc(r.data.confidence||'Expected')} · ${esc(r.date||'date not set')} · ${esc(r.data.status||'Expected')}</small>`;if(r.type==='envelope')extra=`<strong class=amount>${dollars(r.data.limit||0)}</strong><small>${esc(r.data.period||'Monthly')} · ${esc(r.data.category||'Uncategorized')} · planning limit</small>`;if(r.type==='fund'){const target=r.data.target||0,amount=r.data.amount||0;extra=`<strong class=amount>${dollars(amount)}</strong><small>of ${dollars(target)} · ${dollars(r.data.monthlyContribution||0)} planned monthly · ${esc(r.data.goalDate||'no target date')}</small><div class=progress><span style="width:${target?Math.min(100,amount/target*100):0}%"></span></div>`;}if(r.type==='transaction')extra=`<strong class="amount ${r.data.direction==='Income'?'positive':''}">${r.data.direction==='Income'?'+':'−'}${dollars(r.data.amount)}</strong><small>${esc(r.data.scope)} · ${esc(r.data.category)}</small>`;if(r.type==='saving'){const target=r.data.target||0,amount=r.data.amount||0;extra=`<strong class=amount>${dollars(amount)}</strong><small>of ${dollars(target)} saved</small><div class=progress><span style="width:${target?Math.min(100,amount/target*100):0}%"></span></div>`;}if(r.type==='bill')extra=`<strong class=amount>${dollars(r.data.amount||0)}</strong><small>${esc(r.data.cadence)} · due ${esc(r.date||'when entered')}</small>`;if(r.type==='debt')extra=`<strong class=amount>${dollars(r.data.amount||0)}</strong><small>${Number(r.data.apr)||0}% APR · ${dollars(r.data.payment||0)} monthly payment</small>`;if(r.type==='goal'||r.type==='learning')extra=`<div class="progress"><span style="width:${Math.max(0,Math.min(100,Number(r.data.progress)||0))}%"></span></div><small>${Number(r.data.progress)||0}% · ${esc(r.data.milestone||r.data.practice||'At my own pace')}</small>`;if(r.type==='mood')extra=`<div class="feeling-tags">${r.data.feelings.map(f=>`<span>${esc(f.name)} <i>${f.intensity}/5</i></span>`).join('')}</div><small>${esc(r.energy)} energy${r.data.need?' · Need: '+esc(r.data.need):''}</small>`;if(r.type==='habit'){const n=habitCount(r);extra=`<div class="habitflowers">${Array.from({length:Math.min(7,r.data.target)},(_,i)=>`<span class="${i<n?'bloomed':''}">✿</span>`).join('')}</div><div class="cardactions"><small>${n}/${r.data.target} · ${esc(r.data.rhythm)}</small><button class="softbutton" data-action="habit-log" data-id="${r.id}">Log a little care ${icon('plus')}</button></div>`;}return `<article class="recordcard ${r.type==='mood'?'moodcard':''}"><div class="recordhead"><span class="record-icon">${icon(def.icon)}</span><span>${esc(r.date||'Date unknown')} · ${esc(r.type==='application'?r.data.company||def.name:def.name)}</span><button class="iconbutton ${r.favorite?'pinned':''}" data-action="favorite" data-id="${r.id}" aria-label="${r.favorite?'Unfavorite':'Favorite'} ${esc(r.title)}">${icon('heart')}</button></div><button class="recordtitle" data-action="edit" data-id="${r.id}"><h3>${esc(r.title)}</h3></button>${r.data.url&&safeUrl(r.data.url)?`<a class=textlink href="${esc(safeUrl(r.data.url))}" target=_blank rel="noopener noreferrer">Open saved resource ${icon('arrow')}</a>`:''}${r.body?`<p class="recordbody">${esc(r.body.slice(0,240))}${r.body.length>240?'…':''}</p>`:''}${extra}${r.data.photo&&/^data:image\/(jpeg|png|webp);base64,/.test(r.data.photo)?`<img class="memory-photo" src="${esc(r.data.photo)}" alt="${esc(r.title)}" loading="lazy">`:''}<div class="recordmeta">${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${r.links.length?`<span class="tag">${r.links.length} linked</span>`:''}<span class="status">${esc(r.status)}</span></div><div class="cardactions"><button class="textbutton" data-action="edit" data-id="${r.id}">Open my page ↗</button>${['note','idea'].includes(r.type)?`<button class="textbutton" data-action="convert" data-id="${r.id}">Make a task</button>`:''}<button class="iconbutton" data-action="trash" data-id="${r.id}" aria-label="Move ${esc(r.title)} to trash">${icon('trash')}</button></div></article>`}
