function beautySanctuary(){const date=selectedDate||day(),rs=active(store.state),due=dueRituals(date,rs),done=completedRituals(rs,date),products=rs.filter(r=>r.type==='beauty'),selected=['All','Skin','Hair','Body','Grooming','Wellness','Home','Life admin'];return heading('THE SOFT-LIFE SANCTUARY','My beauty <em>rituals.</em>','Care for my skin, hair, body and peace of mind — without turning self-care into another job.','beauty')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">MY DAILY CARE ♡</span><h2>${date===day()?'Today’s':'Selected day’s'} little rituals</h2></div><span class="tag">${due.filter(x=>x.done).length}/${due.length} complete</span></div><p>Morning and evening basics first. On low-energy days, cleansing, moisturizing, sunscreen and oral care are enough. Nothing here requires expensive products.</p><div class="centeractions"><button class="softbutton" data-action="beauty-day" data-offset="-1">← Previous day</button><strong>${esc(date)}</strong><button class="softbutton" data-action="beauty-day" data-offset="1">Next day →</button></div>${due.map(r=>`<div class="category-row"><div><strong>${esc(r.name)}</strong><small>${esc(r.when)} · ${r.minutes} min</small></div><button class="softbutton" data-action="beauty-complete" data-id="${esc(r.id)}" ${r.done?'disabled':''}>${r.done?'✓ Done':'Log ritual ♡'}</button></div>`).join('')}</section><section class="panel"><div class="panelhead"><div><span class="tiny-label">THE COMPLETE RITUAL LIBRARY</span><h2>My grown-woman care menu</h2></div><span class="tag">${beautyRituals.length} rituals</span></div><p>Choose the care you want. You can save a customized version to your beauty cabinet, edit the steps and track products separately.</p><div class="tabs" id="beauty-filters">${selected.map(x=>`<button data-action="beauty-filter" data-category="${esc(x)}" class="${(beautyCategory||'All')===x?'selected':''}">${esc(x)}</button>`).join('')}</div>${beautyRituals.filter(r=>(beautyCategory||'All')==='All'||r.category===beautyCategory).map(r=>`<details class="panel"><summary><strong>${esc(r.name)}</strong> <span class="tag">${esc(r.when)} · ${r.minutes} min</span></summary><ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="caption">${esc(r.note)}</p><button class="softbutton" data-action="beauty-save" data-id="${esc(r.id)}">Save editable ritual ♡</button></details>`).join('')}</section><section class="panel"><div class="panelhead"><h2>My beauty cabinet</h2><span class="tag">${products.length} entries</span></div><p>Keep products, appointments, patch-test notes and routines together. Personal photos stay private; they are not uploaded to the public repository.</p><div class="centeractions"><button class="heart-pill" data-action="new" data-type="beauty">Add a product or routine ♡</button></div>${products.length?products.slice(0,30).map(r=>`<div class="category-row"><div><strong>${esc(r.title)}</strong><small>${esc(r.data?.category||'Beauty')} · ${esc(r.data?.routine||'')}</small></div><button class="softbutton" data-action="edit" data-id="${r.id}">Edit</button></div>`).join(''):'<p class="calmempty">Your cabinet is ready whenever you are.</p>'}</section>`;}
let beautyCategory='All';
function housekeepingPage(){const laundry=laundryCompletionEffects(active(store.state));const today=day(),due=rhythmDue(records('home'),today),done=rhythmCompleted(records('home'),today),d=homeForDay(today),all=records('home').filter(r=>r.data.category==='Cleaning & care'),tasks=weeklyHome.flatMap(w=>w.tasks.map(t=>({day:w.day,title:t})));return heading('MY HOUSE, MY PEACE','The housekeeping <em>sanctuary.</em>','A gentle rotating schedule for laundry, linens, cleaning and decluttering.','home')+homeOperationsPanel()+`<section class="panel"><span class="tiny-label">WEEKLY RHYTHMS ♡</span><h2>${done.length} complete this week · ${due.length} ready</h2><p>${laundry.waiting.length} wardrobe pieces currently waiting for laundry. Mark individual pieces clean after checking them.</p><p>Rhythms reappear when due. A completion is saved once per week, and missed tasks remain available without generating duplicates.</p>${due.map(t=>`<button class="softbutton" data-action="rhythm-complete" data-id="${esc(t.id)}">♡ ${esc(t.title)} ${t.overdue?'· carried forward':''}</button>`).join('')||'<p>All caught up for now ♡</p>'}</section>`+`<section class="panel"><span class="tiny-label">TODAY’S RESET · ${esc(d.day)}</span><h2>${esc(d.name)}</h2><p>Start with one tiny action. Missed tasks can wait without guilt.</p>${d.tasks.map(t=>`<button class="softbutton" data-action="home-add" data-title="${esc(t)}">${icon('plus')} ${esc(t)}</button>`).join('')}</section><section class="panel"><h2>My weekly home rhythm</h2><div class="wardrobe-grid">${weeklyHome.map(w=>`<article class="panel"><h3>${esc(w.day)} · ${esc(w.name)}</h3><p>${w.tasks.map(esc).join(' · ')}</p></article>`).join('')}</div></section><section class="panel"><h2>My cleaning & decluttering records</h2>${all.map(r=>`<button class="softbutton" data-action="edit" data-id="${r.id}">${esc(r.title)} · ${esc(r.status)}</button>`).join('')||'<p>Start by adding a task above.</p>'}</section>`;}
let outfitSeed=0;function cluelessCloset(){const items=records('wardrobe'),clean=items.filter(eligibleForOutfit),outfit=outfitSuggestion(items,'Any',outfitSeed),wear=wardrobeWearSummary(items,day());return heading('THE CLUELESS CLOSET','My virtual <em>wardrobe.</em>','Photograph each item whenever you’re ready. The wardrobe and styling system are ready for your collection.','wardrobe')+`<section class="panel"><span class="tiny-label">THE OUTFIT GENERATOR ♡</span><h2>What shall I wear?</h2><p>Only clean, available clothing is considered. Dresses or a top and bottom are paired with shoes when available.</p><div class="wardrobe-grid">${outfit.pieces.map(r=>`<article class="panel">${r.data.photo?`<img loading="lazy" class="closet-photo" src="${esc(r.data.photo)}" alt="${esc(r.title)}">`:''}<h3>${esc(r.title)}</h3><p>${esc(r.data.brand||'Brand not set')} · ${esc(r.data.size||'Size not set')}</p></article>`).join('')||'<p>Outfit previews will appear once you add your own clothes.</p>'}</div><p>${outfit.complete?'A complete outfit from your closet.':'Add clean shoes and either a dress or a top and bottom to create a complete look.'}</p><button class="heart-pill" data-action="closet-shuffle">Try another ♡</button>${outfit.complete?'<button class="heart-pill" data-action="ootd-wear">I wore this outfit ♡</button>':''}</section><section class="panel"><h2>My wardrobe · ${items.length} pieces</h2><p>${wear.laundry.length} need washing · ${wear.rewear.length} can be considered for rewear · ${wear.careDue.length} professional care checks due</p><p>${clean.length} clean and available · ${items.length-clean.length} worn, in laundry or stored</p><div class="wardrobe-grid">${items.map(r=>`<article class="panel">${r.data.photo?`<img loading="lazy" class="closet-photo" src="${esc(r.data.photo)}" alt="${esc(r.title)}">`:''}<h3>${esc(r.title)}</h3><p>${esc(r.data.brand||'Unbranded')} · ${esc(r.data.size||'Size not set')} · ${esc(r.data.laundry||'Clean')}</p><button class="softbutton" data-action="edit" data-id="${r.id}">Edit piece ♡</button>${['Laundry','Worn','Washing','Drying'].includes(r.data.laundry)?`<button class="softbutton" data-action="garment-clean" data-id="${r.id}">Mark clean ♡</button>`:''}</article>`).join('')||'<p>Your photo-first wardrobe is waiting for you. Add your pieces whenever you like.</p>'}</div></section><section class="panel"><h2>My Fit Passport</h2><p>Keep your real tagged sizes and fit notes here. Brand-specific size predictions will require your measurements and a verified chart; no invented universal sizes.</p></section>`;}
function academyPage(){const w=connectedWorkspace(active(store.state),'academy',day()),term=w.courses.find(x=>x.data.semesterId),termId=term?.data.semesterId,termCourses=w.courses.filter(x=>x.data.semesterId===termId),lessons=w.lessons.filter(x=>x.data.semesterId===termId),assignments=w.assignments.filter(x=>x.data.semesterId===termId),exams=w.exams.filter(x=>x.data.semesterId===termId),transcript=termId?semesterTranscript(active(store.state),termId):[],research=records('note').filter(x=>x.tags.includes('Research notebook')),vocab=records('note').filter(x=>x.tags.includes('Academy vocabulary')&&Array.isArray(x.data.words)),due=academyDueReviews(vocab.flatMap(r=>r.data.words.map(word=>({...word,recordId:r.id,recordTitle:r.title}))),day());return heading('BELLE ACADEMY','The woman I am becoming','A complete semester, built around real learning, steady practice and room for life.','course')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">THE LEARNING CONTRACT</span><h2>${term?'My 16-week semester':'A semester designed for steady progress'}</h2></div><span class="tag">${academySemester.weeks} weeks · ${academySemester.hoursPerWeek} hrs/week</span></div><p>12 hours a week across five courses. The plan includes assignments, review and exams. Every study block is a suggestion until you choose to schedule it. There are no claims of accreditation, a degree or faculty review.</p>${term?`<p><strong>${esc(term.title)}</strong> · ${termCourses.length}/5 courses · ${lessons.filter(x=>x.status==='Done').length}/${lessons.length} weekly learning plans completed · ${exams.filter(x=>x.status==='Done').length}/${exams.length} assessments complete</p><div class="recordgrid">${termCourses.map(card).join('')}</div><form id="academy-study-form" class="formgrid"><label>Course week<select name="week">${Array.from({length:16},(_,i)=>{const n=i+1,plan=lessons.find(x=>x.data.week===n);return `<option value="${n}">Week ${n} · begins ${esc(plan?.date||'')}</option>`;}).join('')}</select></label><label>Available from<input type="time" name="start" value="10:00" required></label><label>Until<input type="time" name="end" value="19:00" required></label><label>Daily study limit (hours)<input name="maxHours" type="number" min="0.5" max="6" step="0.5" value="3"></label><label>Buffer between blocks (minutes)<input name="buffer" type="number" min="0" max="60" value="10"></label><div class="span2"><span class="tiny-label">AVAILABLE DAYS · REST DAYS ARE PROTECTED</span><div class="centeractions">${[['1','Mon'],['2','Tue'],['3','Wed'],['4','Thu'],['5','Fri']].map(([n,label])=>`<label class="checklabel"><input type="checkbox" name="day" value="${n}" checked>${label}</label>`).join('')}<label class="checklabel"><input type="checkbox" name="day" value="6">Sat</label><label class="checklabel"><input type="checkbox" name="day" value="7">Sun</label></div></div><button class="heart-pill">Preview my study week ♡</button></form><div id="academy-study-preview" role="status"><p class="caption">The planner checks existing appointments and shifts, spreads work across your chosen days, and caps focus time each day. Preview first; nothing is scheduled until you approve it.</p></div>`:`<form id="academy-start-form" class="inlineform"><label>First Monday of the term<input type="date" name="start" required></label><button class="heart-pill">Build my full semester ♡</button></form><p class="caption">Creates 5 editable courses, 80 weekly learning plans, 80 weekly assignments and 20 assessment checkpoints. Starting the plan does not book calendar time.</p>`}</section>${term?`<section class="panel"><div class="panelhead"><div><span class="tiny-label">PLACEMENT, WITHOUT LABELS</span><h2>Course diagnostic</h2></div></div><p>A short check helps choose a comfortable starting point. A high score suggests reviewing placement with a human; it never skips course material automatically.</p><form id="academy-diagnostic-form" class="inlineform"><label>Course<select name="course">${termCourses.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select></label><label>Diagnostic score<input name="score" type="number" min="0" max="100" required></label><button class="softbutton">Save diagnostic result</button></form></section><section class="panel"><div class="panelhead"><div><span class="tiny-label">EVIDENCE BEFORE MASTERY</span><h2>Record learning evidence</h2></div></div><p>Mastery uses an 80% target. A score alone cannot clear essential skills or prerequisites that are still unmet.</p><form id="academy-evidence-form" class="formgrid"><label class="span2">Weekly plan<select name="lesson">${lessons.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select></label><label>Score (%)<input name="score" type="number" min="0" max="100" required></label><label class="span2">Evidence and next step<textarea name="evidence" required maxlength="1500" placeholder="What did you make, explain, practice or retrieve? What needs another pass?"></textarea></label><button class="heart-pill">Save my learning evidence ♡</button></form></section><section class="panel"><div class="panelhead"><div><span class="tiny-label">ASSESSMENT & PORTFOLIO</span><h2>Working transcript</h2></div><span class="tag">${assignments.filter(x=>x.data.score!==null).length+exams.filter(x=>x.data.score!==null).length} graded items</span></div><p>Scores are your own evidence and are not official grades. The grade is provisional until all weighted evidence categories have a score; there is no accreditation or faculty review.</p><div class="recordgrid">${transcript.map(t=>`<article class="recordcard"><span class="tiny-label">${esc(t.courseCode)}</span><h3>${esc(t.title.replace(`${t.courseCode} · `,''))}</h3><p>${t.grade===null?'Not graded yet':`Provisional ${t.grade}%`} · ${t.weightAvailable}/100 weight represented</p><small>Assignments ${t.scores.assignments??'—'} · Exams ${t.scores.exams??'—'} · Projects ${t.scores.projects??'—'} · Research ${t.scores.research??'—'} · Mastery ${t.scores.mastery??'—'}</small></article>`).join('')}</div><form id="academy-grade-form" class="formgrid"><label class="span2">Assignment or assessment<select name="item">${[...assignments,...exams].map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select></label><label>Score (%)<input name="score" type="number" min="0" max="100" required></label><label class="span2">Feedback and next steps<textarea name="feedback" maxlength="1200" placeholder="What went well? What would improve the next attempt?"></textarea></label><button class="softbutton">Record assessment evidence</button></form><div class="recordgrid">${assignments.filter(x=>x.status!=='Done').slice(0,5).map(card).join('')}</div></section><section class="panel"><div class="panelhead"><div><span class="tiny-label">RESEARCH WITH CARE</span><h2>Research notebook</h2></div></div><p>Keep question, source provenance, method, limits and your own synthesis together. DreamHub does not invent references or certify novelty.</p><div class="recordgrid">${research.map(card).join('')}</div><form id="academy-research-form" class="formgrid"><label class="span2">Research question<input name="question" minlength="8" required></label><label class="span2">Source title<input name="sourceTitle" required></label><label class="span2">Source URL<input name="sourceUrl" type="url" required></label><label class="span2">Your synthesis<textarea name="claim" maxlength="1500" placeholder="Separate your own interpretation from the source’s claims."></textarea></label><label>Method / search approach<input name="method"></label><label>Limitations and uncertainty<input name="limitations"></label><label class="span2"><input type="checkbox" name="integrity"> I have cited the source and this synthesis is my own.</label><button class="softbutton">Save research note</button></form></section>`:''}<section class="panel"><div class="panelhead"><div><span class="tiny-label">20 WORDS, LITTLE AND OFTEN</span><h2>English vocabulary garden</h2></div><span class="tag">${due.length} reviews due · ${vocab.reduce((n,x)=>n+x.data.words.length,0)} introduced</span></div><p>Introduce 5 foundational and 15 advanced words each week. Introduction is not the same as mastery; spaced recall records confidence over time.</p><form id="academy-vocabulary-form" class="formgrid"><label class="span2">Week label<input name="title" placeholder="Week 1 vocabulary" required></label><label class="span2">Paste exactly 20 distinct words, separated by commas<textarea name="words" required placeholder="The first 5 are foundational; the next 15 are advanced."></textarea></label><button class="softbutton">Add this week’s vocabulary ♡</button></form>${due.slice(0,12).map(x=>{const r=records('note').find(q=>q.id===x.recordId),word=r?.data.words.find(q=>q.word===x.word);return `<article class="category-row"><div><strong>${esc(x.word)}</strong><small>${esc(x.recordTitle)} · due ${esc(x.nextReview)} · ${esc(x.level)}</small></div><div><label class="caption" for="quality-${esc(r.id)}-${esc(x.word)}">Recall 0–5</label><select id="quality-${esc(r.id)}-${esc(x.word)}" data-recall-quality><option value="0">0 · blank</option><option value="1">1 · difficult</option><option value="2">2 · effortful</option><option value="3">3 · recalled</option><option value="4">4 · easy</option><option value="5">5 · effortless</option></select><button class="softbutton" data-action="academy-recall" data-id="${esc(r.id)}" data-word="${esc(word.word)}">Save recall</button></div></article>`;}).join('')||'<p>No vocabulary reviews are due. Add a week of words to begin.</p>'}</section><section class="panel"><h2>My course map · every week</h2>${termCourses.map(c=>`<details class="panel"><summary><strong>${esc(c.title)}</strong> · ${lessons.filter(x=>x.data.courseCode===c.data.courseCode&&x.status==='Done').length}/16 weeks complete</summary><div class="recordgrid">${[...lessons,...assignments,...exams].filter(x=>x.data.courseCode===c.data.courseCode).sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title)).map(card).join('')}</div></details>`).join('')||empty('course')}<a href="#learning" class="textlink">Visit my learning library ↗</a></section><section class="panel"><h2>Academy records</h2><div class="recordgrid">${[...w.courses,...w.lessons,...w.assignments,...w.exams,...w.study].filter(x=>!termId||x.data.semesterId!==termId).map(card).join('')||'<p>New term records are organized in the course map above.</p>'}</div></section>`;}
function artOfLivingPage(){const w=connectedWorkspace(active(store.state),'social',day());const planned=w.summary.planned;return heading('THE ART OF LIVING','A fuller, more audacious life','Culture, classes, friendship, solo dates and new experiences — without sacrificing financial peace.','experiencePlan')+`<section class="panel"><h2>My twelve worlds</h2><div class="recordgrid">${w.worlds.map(x=>`<article class="recordcard"><strong>${esc(x.world)}</strong><p>${x.completed} experiences completed this month</p></article>`).join('')}</div></section><section class="panel"><h2>Coming into my world</h2><p>${planned.length} upcoming cultural plans · ${w.summary.roomForDiscovery} gentle openings for discovery</p><div class="recordgrid">${planned.map(card).join('')||'<p>Start with a free experience and build a beautiful calendar.</p>'}</div></section><section class="panel"><h2>My experience passport</h2><div class="recordgrid">${w.records.filter(x=>!planned.some(p=>p.id===x.id)).map(card).join('')||'<p>Your experiences will live here.</p>'}</div></section>`;}
function lifeTimelinePage(){const rows=lifeTimeline(active(store.state),{...timelineFilters,includeSensitive:timelineFilters.includeSensitive===true});return heading('MY STORY, IN ORDER','Life timeline','Search dated chapters, memories and meaningful moments, with category and privacy filters.')+`<section class="panel"><h2>Find a chapter in time</h2><form id="timeline-filter-form" class="inlineform"><label>Search titles and notes<input type="search" name="query" value="${esc(timelineFilters.query||'')}" placeholder="A person, place, or phrase…"></label><label>From<input type="date" name="from" value="${esc(timelineFilters.from||'')}"></label><label>Through<input type="date" name="to" value="${esc(timelineFilters.to||'')}"></label><label>Category<select name="category"><option value="">All chapters</option>${['Dreams & milestones','Life chapters','Memories','Daily life','Reflection','Calendar','Experiences','Career','Projects','Decisions','Reviews','Mood','Other'].map(x=>`<option value="${esc(x)}" ${timelineFilters.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="checklabel"><input type="checkbox" name="includeSensitive" ${timelineFilters.includeSensitive?'checked':''}>Include private entry titles</label><button class="softbutton">Search timeline</button><button type="button" class="textbutton" data-action="timeline-clear">Clear</button></form></section><section class="panel"><p>${rows.length} dated moments · sensitive entries are shown without previews.</p>${rows.map(x=>`<article class="category-row"><div><small>${esc(x.date)} · ${esc(x.category)}</small><button class="recordtitle" data-action="edit" data-id="${esc(x.id)}"><strong>${esc(x.title)}</strong></button>${x.body?`<p>${esc(x.body.slice(0,220))}</p>`:x.sensitive?'<small>Private entry · open to view</small>':''}</div></article>`).join('')||'<p>Your timeline will bloom as dated moments are saved.</p>'}</section>`;}
function seasonsPage(){const rs=records('season'),current=activeSeason(active(store.state),day());return heading('CHAPTERS OF BECOMING','Personal seasons','Name the chapter you’re in, what you’re making room for, and what you want to remember.','season')+`<section class="panel"><div class="panelhead"><h2>My current season</h2><span class="tag">${current?esc(current.data.theme||current.title):'No active season'}</span></div>${current?`<p>${esc(current.date)}${current.data.end?' → '+esc(current.data.end):' · open-ended'}</p><p>${esc(current.data.intentions||current.body||'Add an intention whenever you are ready.')}</p><p>${esc(current.data.boundaries||'No boundaries written yet.')}</p><button class="softbutton" data-action="edit" data-id="${esc(current.id)}">Tend this chapter</button>`:'<p>Starting a season is optional. Choose a name that feels true today.</p>'}</section><section class="panel"><h2>My season archive</h2><div class="recordgrid">${rs.map(card).join('')||'<p>Past and present chapters will gather here.</p>'}</div></section>`;}
function decisionsPage(){const rs=records('decision');return heading('PAUSE · WEIGH · CHOOSE','Decision Observatory','Lay out options, tradeoffs, assumptions and your own criteria. Scores can clarify a choice; they never choose for you.')+`<section class="panel"><h2>Build a decision matrix</h2><p>Use one line per option: <code>Option | pro; pro | con; con</code>. Criteria use <code>name | weight</code>; ratings use <code>option | criterion | 0–5</code>.</p><form id="decision-matrix-form" class="formgrid"><label class="span2">Decision question<input name="title" required></label><label class="span2">Options, pros and cons<textarea name="options" required placeholder="Stay in role | steady income; familiar | limited growth\nTake new role | stronger pay | longer commute"></textarea></label><label class="span2">Weighted criteria<textarea name="criteria" required placeholder="Compensation | 3\nFlexibility | 2\nGrowth | 2"></textarea></label><label class="span2">Rate each option for each criterion<textarea name="ratings" required placeholder="Stay in role | Compensation | 3\nStay in role | Flexibility | 4\nTake new role | Compensation | 5"></textarea></label><label class="span2">Assumptions and unknowns<textarea name="assumptions"></textarea></label><label>Review on<input type="date" name="revisit"></label><button class="heart-pill">Compare and save my matrix ♡</button></form></section><section class="panel"><h2>Choices I’m holding</h2><div class="recordgrid">${rs.map(card).join('')||'<p>No decision is required right now.</p>'}</div></section>`;}
function energyEconomicsPage(){const logs=records('note').filter(r=>r.tags.includes('Energy Economics'));return heading('CAPACITY IS INFORMATION','Energy Economics','Name your available energy and time. See a feasible shortlist without turning capacity into a score of your worth.')+`<section class="panel"><h2>Choose a realistic pocket</h2><form id="energy-plan-form" class="formgrid"><label>Energy available<select name="energy"><option value="1">Low</option><option value="2" selected>Medium</option><option value="3">High</option></select></label><label>Minutes available<input name="minutes" type="number" min="5" max="1440" value="60" required></label><p class="caption span2">Tasks are ranked using your entered reward estimate, due date and energy fit. Nothing is completed or scheduled automatically.</p><button class="heart-pill">Preview a feasible plan ♡</button></form><div id="energy-plan-result" role="status"></div></section><section class="panel"><h2>Past energy check-ins</h2><div class="recordgrid">${logs.map(card).join('')||'<p>Energy is optional to track. A single check-in is enough.</p>'}</div></section>`;}
function opportunitiesPage(){const rs=records('opportunity');return heading('POSSIBILITIES, KEPT GENTLY','Opportunity Vault','Save roles, business ideas, invitations and creative possibilities. Your criteria shape the score; the final call stays yours.','opportunity')+`<section class="panel"><div class="panelhead"><h2>My saved possibilities</h2><span class="tag">${rs.length} saved</span></div><div class="recordgrid">${rs.sort((a,b)=>(b.data.score??-1)-(a.data.score??-1)).map(card).join('')||'<p>Save an opportunity when you want to remember it. There is no pressure to act.</p>'}</div></section><section class="panel"><h2>Review my criteria</h2><form id="opportunity-score-form" class="formgrid"><label class="span2">Opportunity<select name="id">${rs.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select></label><label class="span2">My criteria and weights, one per line: name | weight<textarea name="criteria" required placeholder="Pay | 3\nFlexibility | 2\nMeaning | 1"></textarea></label><label class="span2">Rate this opportunity, one per line: name | 0–5<textarea name="ratings" required placeholder="Pay | 4\nFlexibility | 5\nMeaning | 3"></textarea></label><button class="softbutton" ${rs.length?'':'disabled'}>Save my weighted comparison</button></form><p class="caption">A score summarizes your own ratings and weights. It is not an AI recommendation or a probability of success.</p></section>`;}
function sundaySalonPage(){const date=day(),d=new Date(date+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));const monday=day(d),summary=sundaySalon(active(store.state),monday),reviews=records('review');return heading('A KIND LOOK BACK','The Sunday Salon','Notice what happened, name what mattered, and make one humane plan for what comes next.','review')+`<section class="panel"><div class="panelhead"><h2>My week · ${esc(summary.weekStart)} to ${esc(summary.endDate)}</h2><span class="tag">${summary.wins.length} wins logged</span></div><div class="recordgrid"><article class="recordcard"><strong>Things I completed</strong><p>${summary.wins.map(esc).join(' · ')||'Wins can be small, quiet or simply getting through.'}</p></article><article class="recordcard"><strong>Money I entered</strong><p>${dollars(summary.income)} income · ${dollars(summary.spending)} spending · recorded items only</p></article><article class="recordcard"><strong>My week, in little signals</strong><p>${summary.moods} mood check-ins · ${summary.journalEntries} journal/diary pages · ${summary.events.length} saved events · ${summary.experiences.length} completed experiences</p></article></div><p>${summary.unfinished.length} open tasks from this week. You can carry one forward, change it, or let it go.</p></section><section class="panel"><h2>My review archive</h2><div class="recordgrid">${reviews.map(card).join('')||'<p>Save a review when it feels useful. No streaks or catch-up work.</p>'}</div><button class="heart-pill" data-action="new" data-type="review">Write this week’s reflection ♡</button></section>`;}
function spendingPolicyStatus(policy,candidate=null){return evaluateSpendingPolicy(policy,records('transaction'),{candidate,date:candidate?.date||day()});}
function moneyPolicyPanel(){const activePolicies=records('policy').filter(p=>p.data.category==='Money'&&Number.isSafeInteger(p.data.limit)&&p.data.limit>0);return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">MY OWN SPENDING RULES</span><h2>Money policies</h2></div><a href="#policies" class="textlink">Edit policies ↗</a></div>${activePolicies.map(p=>{const status=spendingPolicyStatus(p);return status?`<div class="category-row"><div><strong>${esc(p.title)}</strong><small>${esc(status.period)} · ${esc(status.spendingCategory)} · ${dollars(status.spent)} of ${dollars(status.limit)} recorded</small></div><span class="tag">${status.exceeded?`Over by ${dollars(status.projected-status.limit)}`:`${dollars(status.remaining)} left`}</span></div>`:''}).join('')||'<p>No spending guardrails set. Add a Money policy to see your own limits alongside transactions.</p>'}<p class="caption">These are local estimates from entered transactions. Saving a purchase beyond a limit asks whether you want to continue; DreamHub never blocks or moves money.</p></section>`;}
function policiesPage(){const rs=records('policy'),money=rs.filter(p=>p.data.category==='Money'&&Number.isSafeInteger(p.data.limit)&&p.data.limit>0);return heading('MY STANDARDS, IN MY OWN WORDS','Personal Policies','Write the boundaries and decision rules that protect your time, money and care. Review reminders stay off unless you opt in.','policy')+`${money.length?`<section class="panel"><h2>Money guardrails</h2>${money.map(p=>{const s=spendingPolicyStatus(p);return s?`<article class="category-row"><div><strong>${esc(p.title)}</strong><small>${esc(s.period)} · ${esc(s.spendingCategory)} · ${dollars(s.spent)} recorded against ${dollars(s.limit)}</small></div><span class="tag">${s.exceeded?`Over by ${dollars(s.projected-s.limit)}`:`${dollars(s.remaining)} remaining`}</span></article>`:''}).join('')}<p class="caption">Entered transactions only. Private records remain local. A limit prompts you before a saved expense crosses it; it never blocks a purchase.</p></section>`:''}<section class="panel"><h2>My policies</h2><div class="recordgrid">${rs.map(card).join('')||'<p>Keep a principle here when it helps you make a decision with less friction.</p>'}</div>${rs.some(p=>p.data.remind)?'<p class="caption">A review reminder is opted in for selected policies. Browser notifications also require the separate reminder permission.</p>':''}</section>`;}
function microAdventuresPage(){const ideas=active(store.state).filter(r=>['experiencePlan','experience'].includes(r.type)&&r.status!=='Done');return heading('A LITTLE DELIGHT, WITHIN MY REAL LIFE','Micro-Adventures Generator','Pick from places and ideas you saved yourself, within the budget, time, setting and energy you choose.','experiencePlan')+`<section class="panel"><h2>Wish list and completed visits</h2><p>${experienceLedger(active(store.state)).visited} visited · ${experienceLedger(active(store.state)).wished} wished or planned. Add your own place, source and notes; completion is recorded only when you mark it done.</p><button class="softbutton" data-action="new" data-type="experience">Add a place or visited experience ♡</button><div class="recordgrid">${records('experience').map(card).join('')||'<p>Start with a place you want to remember or a place you have visited.</p>'}</div></section><section class="panel"><h2>Save my own adventure ideas</h2><p>Only your saved ideas can be suggested. No events, prices or opening hours are invented.</p><button class="softbutton" data-action="new" data-type="experiencePlan">Add an adventure idea ♡</button><form id="adventure-form" class="formgrid"><label>Maximum budget (USD)<input name="budget" inputmode="decimal" value="0" required></label><label>Time available (minutes)<input name="minutes" type="number" min="5" max="1440" value="90"></label><label>Energy<select name="energy"><option>Low</option><option selected>Medium</option><option>High</option></select></label><label>Setting<select name="setting"><option>Any</option><option>Indoor</option><option>Outdoor</option></select></label><button class="heart-pill">Surprise me from my saved ideas ♡</button></form><div id="adventure-result" role="status">${adventureChoice?`<article class="recordcard"><h3>${esc(adventureChoice.title)}</h3><p>${esc(adventureChoice.data.location||adventureChoice.data.place||'Location not entered')} · ${dollars(adventureChoice.data.amount||0)} estimate · ${Number(adventureChoice.data.duration)||30} minutes</p><button class="softbutton" data-action="edit" data-id="${esc(adventureChoice.id)}">Review my idea</button></article>`:'<p>Choose constraints, then draw one idea.</p>'}</div></section><section class="panel"><h2>My saved adventure ideas</h2><div class="recordgrid">${ideas.map(card).join('')||'<p>Add a few ideas before asking for a surprise.</p>'}</div></section>`;}
function futureMuseumPage(){
 const visions=[...records('goal'),...records('wish'),...records('season')],snapshots=records('memory').filter(r=>r.data.snapshotLocked||r.tags.includes('Future Museum')),editing=snapshots.find(r=>r.id===snapshotEditId),letters=records('note').filter(x=>x.data?.futureLetter),due=dueFutureLetters(letters,day()),revealed=letters.filter(x=>x.data.futureLetter.status==='revealed'),moments=annualMoments(active(store.state),annualYear);
 const editForm=editing?`<section class="panel"><h2>Intentionally edit this archived snapshot</h2><p>This changes only the saved copy. Current goals and seasons stay untouched.</p><form id="future-snapshot-edit-form" class="formgrid"><input type="hidden" name="id" value="${esc(editing.id)}"><label class="span2">Snapshot title<input name="title" value="${esc(editing.data.snapshot?.title||editing.title)}" required></label><label>Captured date<input type="date" name="date" value="${esc(editing.data.snapshot?.capturedAt||editing.date)}" required></label>${(editing.data.snapshot?.entries||[]).map((entry,i)=>`<fieldset class="span2"><legend>${esc(entry.type)} · ${esc(entry.date||'No source date')}</legend><label>Copied aspiration<input name="entry-title-${i}" value="${esc(entry.title)}" required></label><label>Copied note<textarea name="entry-body-${i}">${esc(entry.body||'')}</textarea></label></fieldset>`).join('')}<div class="centeractions span2"><button class="heart-pill">Save intentional changes ♡</button><button type="button" class="softbutton" data-action="snapshot-edit-cancel">Cancel</button></div></form></section>`:'';
 return heading('ASPIRATIONS, PRESERVED WITH CARE','The Future Museum','Save hopes, seal a letter for a future date, and revisit the moments you chose to keep.')+
 `<section class="panel"><h2>Choose what belongs in a snapshot</h2><form id="future-snapshot-form" class="formgrid"><label class="span2">Snapshot title<input name="title" placeholder="My hopes for this season" required></label><div class="span2">${visions.map(x=>`<label class="checklabel"><input type="checkbox" name="entry" value="${esc(x.id)}">${esc(types[x.type]?.name||x.type)} · ${esc(x.title)}</label>`).join('')||'<p>Add a goal, wish or season first. You choose what to preserve.</p>'}</div><button class="heart-pill" ${visions.length?'':'disabled'}>Preserve this snapshot ♡</button></form></section>${editForm}`+
 `<section class="panel"><span class="tiny-label">A LETTER, WHEN YOU’RE READY</span><h2>Write to a future you</h2><form id="future-letter-form" class="formgrid"><label>Letter title<input name="title" maxlength="240" required placeholder="Open this on my birthday"></label><label>Reveal date<input name="revealDate" type="date" min="${esc(day())}" required></label><label class="span2">Your letter<textarea name="body" maxlength="20000" rows="8" required placeholder="Your words stay sealed in the app until this date…"></textarea></label><button class="heart-pill">Seal this letter ♡</button></form><p class="caption">Letters are marked sensitive. On or after the date, the Future Museum offers an in-app reveal when you open this page. It does not send a notification.</p></section>`+
 `<section class="panel"><h2>Letters ready to open</h2>${due.map(x=>`<article class="recordcard"><strong>${esc(x.title)}</strong><small>Reveal date · ${esc(x.data.futureLetter.revealDate)}</small><p>Still sealed until you choose to open it.</p><button class="heart-pill" data-action="future-reveal" data-id="${esc(x.id)}">Reveal my letter ♡</button></article>`).join('')||'<p>No sealed letters are due to open yet.</p>'}${revealed.length?`<h3>Opened letters</h3>${revealed.map(x=>`<article class="recordcard"><strong>${esc(x.title)}</strong><small>Opened ${esc(x.data.futureLetter.revealedAt)}</small><p>${esc(x.body)}</p></article>`).join('')}`:''}</section>`+
 `<section class="panel"><h2>A year in moments</h2><form id="annual-moments-form" class="inlineform"><label>Year<input name="year" type="number" min="1900" max="9999" value="${annualYear}"></label><button class="softbutton">Review this year</button></form>${moments.map(m=>`<article class="category-row"><strong>${new Date(annualYear,m.month-1).toLocaleString('en',{month:'long'})}</strong><span>${m.items.map(x=>`<button class="textbutton" data-action="edit" data-id="${esc(x.id)}">${esc(x.title)}</button>`).join(' · ')}</span></article>`).join('')||'<p>No dated, non-sensitive memories or writing saved for this year yet.</p>'}${moments.length?'<button class="heart-pill" data-action="annual-moments-save">Save my annual review ♡</button>':''}</section>`+
 `<section class="panel"><h2>Snapshots across time</h2><div class="recordgrid">${snapshots.map(r=>`<article class="recordcard"><small>${esc(r.date||r.data.snapshot?.capturedAt||'')}</small><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><small>${(r.data.snapshot?.entries||[]).map(x=>esc(x.title)).join(' · ')}</small><button class="softbutton" data-action="snapshot-edit" data-id="${esc(r.id)}">Intentionally edit this archived snapshot</button></article>`).join('')||'<p>Your future self has room to change. Save a snapshot only when you want to remember this version.</p>'}</div></section>`;
}
function recoveryPage(){const digest=recoveryDigest(active(store.state),{daysAway:recoveryGap,today:day(),limit:5});return heading('NO CATCH-UP REQUIRED','Gentle Recovery Room','A calm re-entry point: a few saved commitments, with permission to choose none of them.')+`<section class="panel"><div class="panelhead"><h2>Welcome back</h2><span class="tag">${recoveryGap?`${recoveryGap} days since this device was opened`:'Here whenever you need it'}</span></div><p>${esc(digest.message)}</p>${digest.items.map(x=>`<article class="category-row"><button class="recordtitle" data-action="edit" data-id="${esc(x.id)}"><strong>${esc(x.title)}</strong></button><small>${esc(types[x.type]?.name||x.type)}${x.date?' · '+esc(x.date):''}</small></article>`).join('')||'<p>There is nothing urgent waiting here. You can simply look around.</p>'}<div class="centeractions"><a href="#home" class="heart-pill">Go to today ♡</a><button class="softbutton" data-action="recovery-dismiss">Hide the welcome panel</button></div></section>`;}
function homeOperationsPanel(){const options=compareResidences(active(store.state)),due=dueHomeAdmin(active(store.state),{today:day()}),items=records('homeItem'),admin=records('homeAdmin'),checklists=records('homeChecklist');return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">HOME & MOVING ADMIN</span><h2>Compare places and keep home details together</h2></div><span class="tag">${options.length} options · ${due.length} due reviews</span></div><p>Apartment totals use only your entered rent, utilities, monthly fees and move-in costs. No listing, neighborhood or eligibility details are verified by DreamHub.</p><div class="recordgrid">${options.map(x=>`<article class="recordcard"><h3>${esc(x.title)}</h3><p>${esc(x.data.address||'Neighborhood not entered')}</p><div class="money-stats"><div><span>MONTHLY COST</span><strong>${dollars(x.monthlyCostCents)}</strong></div><div><span>MOVE-IN COST</span><strong>${dollars(x.moveInCostCents)}</strong></div></div><p>${esc(x.data.mustHaves||'Add must-haves and tradeoffs to compare.')}</p><div class="cardactions"><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">Edit option</button><button class="iconbutton" data-action="trash" data-id="${esc(x.id)}" aria-label="Move ${esc(x.title)} to trash">${icon('trash')}</button></div></article>`).join('')||'<p>No apartment options saved yet.</p>'}</div><div class="centeractions"><button class="softbutton" data-action="new" data-type="property">Add apartment option ♡</button><button class="softbutton" data-action="new" data-type="homeItem">Add inventory or warranty ♡</button><button class="softbutton" data-action="new" data-type="homeAdmin">Add maintenance, errand or renewal ♡</button></div><h3>Home inventory and warranties</h3><div class="recordgrid">${items.map(x=>`<article class="recordcard"><h4>${esc(x.title)}</h4><p>${esc(x.data.category||'Item')} · ${esc(x.data.location||'Storage location not entered')}</p><small>${x.data.purchaseDate?`Purchased ${esc(x.data.purchaseDate)} · `:''}${x.data.warrantyEnd?`Warranty through ${esc(x.data.warrantyEnd)}`:'No warranty date entered'}${due.some(d=>d.id===x.id)?' · review due':''}</small><div class="cardactions">${due.some(d=>d.id===x.id)?`<button class="softbutton" data-action="home-maintenance-complete" data-id="${esc(x.id)}">Mark reviewed</button>`:''}<button class="textbutton" data-action="edit" data-id="${esc(x.id)}">Edit item</button><button class="iconbutton" data-action="trash" data-id="${esc(x.id)}" aria-label="Move ${esc(x.title)} to trash">${icon('trash')}</button></div></article>`).join('')||'<p>No home inventory saved yet.</p>'}</div><h3>Maintenance and renewals needing review</h3>${admin.map(x=>`<div class="category-row"><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">${esc(x.title)}</button><small>${esc(x.data.category||'Home admin')} · ${esc(x.data.dueDate||'No due date')} · ${esc(x.data.frequency||'One-time')}${x.data.lastCompleted?` · last completed ${esc(x.data.lastCompleted)}`:''}</small>${due.some(d=>d.id===x.id)?`<button class="softbutton" data-action="home-maintenance-complete" data-id="${esc(x.id)}">Mark complete</button>`:''}</div>`).join('')||'<p>No home administration items yet.</p>'}<p>Due now: ${due.length}. Recurring maintenance advances from its due date after you mark it complete. One-time items move to Done.</p><section class="home-move-plan"><h3>Build a moving timeline</h3><p>Enter the steps and how many days before your move you want each one. Review the derived dates before adding tasks.</p><form id="home-move-plan-form" class="formgrid"><label>Target move date<input name="moveDate" type="date" required></label><label class="span2">Tasks, one per line: task | days before move<textarea name="items" required placeholder="Confirm lease and fees | 90&#10;Book movers | 30&#10;Pack essentials | 1"></textarea></label><button class="heart-pill">Preview my timeline ♡</button></form>${moveTimelineDraft?`<div id="home-move-preview" role="status"><h4>${moveTimelineDraft.tasks.length} tasks before ${esc(moveTimelineDraft.moveDate)}</h4>${moveTimelineDraft.tasks.map(t=>`<div class="category-row"><span>${esc(t.title)}</span><small>${esc(t.date)}</small></div>`).join('')}<button class="softbutton" data-action="home-move-approve">Add selected timeline to Tasks ♡</button></div>`:'<p class="caption">Nothing is saved until you review and approve the preview.</p>'}</section><section class="home-doc-checklists"><h3>Document and move checklists</h3><form id="home-checklist-form" class="formgrid"><label>Checklist name<input name="title" required maxlength="120" placeholder="Lease application documents"></label><label>Review date<input name="dueDate" type="date"></label><label class="span2">Items, one per line<textarea name="items" required placeholder="Photo ID&#10;Income documents&#10;Rental references"></textarea></label><button class="softbutton">Save checklist ♡</button></form><div class="recordgrid">${checklists.map(c=>{const p=homeChecklistProgress(c);return `<article class="recordcard"><h4>${esc(c.title)} · ${p.done}/${p.total}</h4>${p.items.map(i=>`<button class="checkrow ${i.done?'checked':''}" data-action="home-check-toggle" data-id="${esc(c.id)}" data-index="${i.index}" data-checked="${i.done?'true':'false'}" aria-pressed="${i.done}">${i.done?'✓':'○'} ${esc(i.title)}</button>`).join('')}<div class="cardactions"><button class="textbutton" data-action="edit" data-id="${esc(c.id)}">Edit checklist</button><button class="iconbutton" data-action="trash" data-id="${esc(c.id)}" aria-label="Move ${esc(c.title)} to trash">${icon('trash')}</button></div></article>`;}).join('')||'<p>No checklists yet. Add the documents or steps you need to track.</p>'}</div></section><p class="caption">Home option, inventory, warranty, document, errand, maintenance and renewal records are editable, recoverable and included in workspace export.</p></section>`;}
function relationshipsGardenPage(){const people=records('person'),occasions=optedInOccasions(active(store.state),{from:day(),to:day(new Date(Date.now()+90*86400000))});return heading('A GENTLER WAY TO STAY CONNECTED','My <em>relationship garden.</em>','Keep people and meaningful dates in your own words. Date reminders appear only when you opt in.','person')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">OPT-IN OCCASIONS</span><h2>Dates I chose to remember</h2></div><span class="tag">${occasions.length} in 90 days</span></div><p>No messages are sent. This is an in-app list that appears when you open DreamHub.</p><div class="recordgrid">${occasions.map(x=>`<article class="recordcard"><h3>${esc(x.title)}</h3><p>${esc(x.date)} · ${esc(x.data.occasion||'Occasion')}${x.data.leadDays?` · ${esc(x.data.leadDays)} days notice`:''}</p>${x.links.length?`<small>Linked person: ${esc(active(store.state).find(p=>p.id===x.links[0])?.title||'Saved person')}</small>`:''}<button class="textbutton" data-action="edit" data-id="${esc(x.id)}">Edit reminder</button><button class="iconbutton" data-action="trash" data-id="${esc(x.id)}" aria-label="Move ${esc(x.title)} to trash">${icon('trash')}</button></article>`).join('')||'<p>No opted-in dates coming up. Add one only when you want the reminder.</p>'}</div><div class="centeractions"><button class="softbutton" data-action="new" data-type="occasion">Add an opted-in occasion ♡</button><button class="softbutton" data-action="new" data-type="person">Add a person ♡</button></div></section><section class="recordgrid">${people.map(card).join('')||'<p>No connections saved yet.</p>'}</section><p class="caption">All dates are stored locally with the workspace. No outreach is initiated automatically.</p>`;}
function petCarePage(){const plans=records('petCare').sort((a,b)=>(a.data.next||'9999').localeCompare(b.data.next||'9999'));return heading('FREYJA’S LITTLE LIFE','Her <em>care corner.</em>','Keep supplies and care steps together. Medical and care notes start private; you choose what to record.','pet')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">CARE SCHEDULE & PREPARATION</span><h2>${plans.length} saved care plans</h2></div></div><div class="centeractions"><button class="softbutton" data-action="new" data-type="petCare">Add vet, medication or preventive care ♡</button><button class="softbutton" data-action="new" data-type="pet">Add supply or pet note ♡</button></div><div class="recordgrid">${plans.map(x=>`<article class="recordcard"><h3>${esc(x.title)}</h3><p>${esc(x.data.category||'Care')} · next ${esc(x.data.next||'date not set')}</p><p>${esc(x.data.provider||'Provider not entered')} · ${dollars(x.data.amount||0)} estimated</p><small>${esc(x.data.frequency||'One-time reminder')}${x.data.lastCompleted?` · last completed ${esc(x.data.lastCompleted)}`:''}</small><div class="cardactions"><button class="softbutton" data-action="pet-care-log" data-id="${esc(x.id)}">Log completed care</button><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">Edit</button><button class="iconbutton" data-action="trash" data-id="${esc(x.id)}" aria-label="Move ${esc(x.title)} to trash">${icon('trash')}</button></div></article>`).join('')||'<p>No care plans yet. Add only the care you want to track.</p>'}</div><p class="caption">Care information is sensitive and local by default. This does not replace veterinary guidance or send appointment reminders outside the app.</p></section><section class="recordgrid">${records('pet').map(card).join('')||''}</section>`;}
function mediaLibraryPage(){const shelf=mediaShelf(active(store.state)),counts=new Map();for(const x of shelf)counts.set(x.data.status,(counts.get(x.data.status)||0)+1);return heading('MY LITTLE MEDIA SHELF','Stories I want to keep','Track books, films, series, music, podcasts and games with my own progress and source details.','media')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">MY LIBRARY</span><h2>${shelf.length} saved items</h2></div><button class="softbutton" data-action="new" data-type="media">Add a book, film or favorite ♡</button></div><p>${['Want to try','Started','Paused','Finished'].map(x=>`${esc(x)}: ${counts.get(x)||0}`).join(' · ')}</p><div class="recordgrid">${shelf.map(card).join('')||'<div class="emptylarge"><h2>Your media shelf is open.</h2><p>Save a title and where to find it. DreamHub does not verify availability or stream media.</p></div>'}</div><p class="caption">Source links are user-entered. Ratings and progress are personal notes.</p></section>`;}
function modulePage(){if(route==='collections')return collectionsPage();if(route==='people')return relationshipsGardenPage();if(route==='freyja')return petCarePage();if(route==='library')return mediaLibraryPage();if(route==='relationships')return relationshipsPage();if(route==='journal'||route==='diary')return writingPage(route);const ts=routeTypes[route],copy=routeCopy[route]||['A LITTLE ROOM FOR THIS PART OF ME','Keep the things that matter, in your own words.'];let items=listFor(route).filter(r=>(tab==='all'||r.type===tab)&&(!filter||`${r.title} ${r.body} ${r.tags.join(' ')} ${JSON.stringify(r.data)}`.toLowerCase().includes(filter.toLowerCase())));if(route==='scenarios')return financeScenarioPage();if(route==='inbox')return inboxPage();if(route==='social')return artOfLivingPage();if(route==='timeline')return lifeTimelinePage();if(route==='seasons')return seasonsPage();if(route==='decisions')return decisionsPage();if(route==='energy')return energyEconomicsPage();if(route==='opportunities')return opportunitiesPage();if(route==='reviews')return sundaySalonPage();if(route==='policies')return policiesPage();if(route==='experiences')return microAdventuresPage();if(route==='future')return futureMuseumPage();if(route==='recovery')return recoveryPage();if(route==='academy')return academyPage();if(route==='tasks')return taskPage();if(route==='habits')return habitPlanningPage();if(route==='goals')return goalsPage();if(route==='career'||route==='studio')return pipelinePage();if(route==='grimoire')return grimoire();if(route==='treasury')return treasury();if(route==='beauty')return beautySanctuary();if(route==='sanctuary')return housekeepingPage();if(route==='wardrobe')return cluelessCloset();return heading(copy[0],titleFor(route),copy[1],ts[0])+`<div class="toolbar"><div class="tabs"><button class="${tab==='all'?'selected':''}" data-action="filter-type" data-type="all">All my pages <span>${listFor(route).length}</span></button>${ts.length>1?ts.map(t=>`<button class="${tab===t?'selected':''}" data-action="filter-type" data-type="${t}">${types[t].plural}</button>`).join(''):''}<button class="${tab==='favorites'?'selected':''}" data-action="favorites">♡ Favorites</button></div><label class="inline-search">${icon('search')}<input data-filter placeholder="Find in this space…" value="${esc(filter)}" aria-label="Filter this space"></label></div>${route==='mood'?moodSummary():''}<div id="record-results" class="recordgrid">${items.length?items.map(card).join(''):empty(ts[0])}</div>`}
function titleFor(r){const names={journal:'Dear, <em>beautiful me.</em>',diary:'My days, <em>remembered.</em>',mood:'Every feeling, <em>welcome.</em>',grimoire:'The <em>grimoire.</em>',dreams:'Somewhere in <em>my dreams.</em>',ideas:'The <em>idea garden.</em>',goals:'A life I’m <em>growing into.</em>',career:'My next <em>chapter.</em>',studio:'A. Halliwell <em>Studio.</em>',habits:'Little rituals. <em>Deep roots.</em>',sanctuary:'My <em>sanctuary.</em>',freyja:'For my girl, <em>Freyja.</em>',reviews:'The <em>Sunday salon.</em>',wishlist:'The <em>wish room.</em>',memories:'My <em>memory museum.</em>'};return names[r]||esc(routeName(r))+'.'}
function moodSummary(){const logs=records('mood').slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-7),counts={};logs.forEach(r=>r.data.feelings.forEach(f=>counts[f.name]=(counts[f.name]||0)+1));return `<section class="mood-summary"><div><span class="tiny-label">MY RECENT EMOTIONAL WEATHER</span><p>${logs.length?logs.length+' check-ins, held with care.':'Nothing to analyze. Just somewhere to land.'}</p></div><div class="feeling-tags">${Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([m,n])=>`<span>${esc(m)} · ${n}</span>`).join('')}</div><small>Counts from your last seven entries, not a diagnosis or a trend prediction.</small></section>`}
function weeklyResetPanel(){const tasks=records('task').filter(x=>x.status!=='Done');return `<section class="panel"><span class="tiny-label">A RESET THAT FITS YOUR WEEK ♡</span><h2>Weekly reset & a gentler day</h2><p>See the open work beside the time you want to spend. Choose a small plan; nothing is rescheduled without you.</p><div class="lowergrid twocol"><form id="weekly-reset-form" class="formgrid"><label>Week containing<input type="date" name="weekOf" value="${day()}" required></label><label>Minutes I want available<input type="number" name="capacity" min="0" max="10080" value="600" required></label><label>Typical energy<select name="energy"><option>Low</option><option selected>Medium</option><option>High</option></select></label><button class="softbutton">Review my week</button><div id="weekly-reset-result" class="span2" role="status">${weekResetPreview?`${weekResetPreview.openTasks} open tasks · ${weekResetPreview.estimatedTaskMinutes} estimated minutes`:''}</div></form><form id="minimum-day-form" class="formgrid"><label>Date<input type="date" name="date" value="${day()}" required></label><label>Capacity in minutes<input type="number" name="capacity" min="0" max="480" value="60" required></label><label>Energy<select name="energy"><option selected>Low</option><option>Medium</option><option>High</option></select></label><button class="softbutton">Find my minimum viable day</button><div id="minimum-day-result" class="span2" role="status">${minDayPreview?`${minDayPreview.selected.length} possible small steps · ${minDayPreview.blocked.length} blocked`:'Rest, essentials, and one small step all count.'}</div></form></div></section>`;}
function taskPage(){const items=listFor('tasks').filter(r=>(!r.data.parentTaskId||!records('task').some(parent=>parent.id===r.data.parentTaskId))&&(!filter||r.title.toLowerCase().includes(filter.toLowerCase())));return heading('A LITTLE STRUCTURE FOR MY BIG DREAMS','Now. Next. <em>When I’m ready.</em>','Choose a next action, give it a little time, and leave room to be human.','task')+weeklyResetPanel()+`<div class="toolbar"><label class="inline-search">${icon('search')}<input data-filter aria-label="Filter tasks" placeholder="Find a little next step…" value="${esc(filter)}"></label><button class="softbutton" data-action="new" data-type="project">${icon('plus')} New project</button><a href="#focus" class="textlink">A little focus ↗</a></div><div class="taskboard">${['Now','Next','Later','Done'].map(status=>`<section class="boardcolumn"><div class="boardheading"><span class="status-dot ${status.toLowerCase()}"></span><h2>${status}</h2><span>${items.filter(r=>(['Now','Next','Later','Done'].includes(r.status)?r.status:'Next')===status).length}</span></div>${items.filter(r=>(['Now','Next','Later','Done'].includes(r.status)?r.status:'Next')===status).map(r=>{const ready=r.type==='task'?taskReadiness(r,active(store.state)):null,due=r.type==='task'?flexibleDueStatus(r,day()):null;return `<div class="boardcard"><div class="cardactions"><span class="tag">${r.type==='project'?'Project':esc(r.data.priority||'Gentle')}</span><button class="iconbutton ${r.favorite?'pinned':''}" data-action="favorite" data-id="${r.id}" aria-label="Pin ${esc(r.title)}">${icon('star')}</button></div><button class="recordtitle" data-action="edit" data-id="${r.id}"><h3>${esc(r.title)}</h3></button>${r.data.nextAction?`<p>Next: ${esc(r.data.nextAction)}</p>`:''}${r.data.stuckBecause?`<p class="caption">Blocked by: ${esc(r.data.stuckBecause)}</p>`:''}${r.type==='task'?(()=>{const children=records('task').filter(x=>x.data.parentTaskId===r.id);return `<div class="subtask-list"><strong>${children.filter(x=>x.status==='Done').length}/${children.length} tiny steps complete</strong>${children.map(c=>`<div class="mini-task ${c.status==='Done'?'done':''}"><button class="taskcheck ${c.status==='Done'?'checked':''}" data-action="complete" data-id="${esc(c.id)}" aria-label="${c.status==='Done'?'Reopen':'Complete'} ${esc(c.title)}">${c.status==='Done'?icon('check'):''}</button><button class="tasktext" data-action="edit" data-id="${esc(c.id)}"><strong>${esc(c.title)}</strong><span>${c.minutes||15} min · ${esc(c.energy)} energy</span></button></div>`).join('')}<button class="textbutton" data-action="task-subtask" data-id="${esc(r.id)}">Add a tiny step +</button></div>`;})():''}<small>${r.minutes||15} min · ${esc(r.energy)} energy${r.data.context&&r.data.context!=='Anywhere'?' · '+esc(r.data.context):''}${r.data.location?' · '+esc(r.data.location):''}</small><div class="cardactions"><small>${due?.window.mode==='window'?`${esc(due.window.start)} – ${esc(due.window.end)} · ${due.state}`:due?.window.mode==='before'?`Before ${esc(due.window.start)}`:due?.window.mode==='someday'?'When I’m ready':esc(due?.window.start||r.date)}${ready&&!ready.ready?` · waiting on ${ready.pending.map(x=>esc(x.title)).join(', ')||ready.missing.length+' missing task(s)'}`:''}</small><button class="taskcheck ${status==='Done'?'checked':''}" data-action="complete" data-id="${r.id}" aria-label="${status==='Done'?'Reopen':'Complete'} task">${icon('check')}</button></div></div>`}).join('')}<button class="boardadd" data-action="new" data-type="task" data-status="${status}">${icon('plus')} A little next step</button></section>`).join('')}</div>`}
function habitPlanningPage(){const templates=store.state.settings.habitTemplates||[],habits=records('habit');return heading('SOFT RHYTHMS, STEADY ROOTS','Little rituals. <em>Deep roots.</em>','Build a rhythm that can pause, restart, and count a week without a perfect streak.','habit')+`<section class="panel"><h2>Create a reusable habit template</h2><form id="habit-template-form" class="formgrid"><label>What would feel good to repeat?<input name="name" maxlength="120" required></label><label>Rhythm<select name="rhythm"><option>Daily</option><option selected>Weekly</option><option>Ongoing</option></select></label><label>Weekly target count<input name="target" type="number" min="1" max="100" value="3"></label>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label class="checklabel"><input type="checkbox" name="weekday" value="${i}">${d}</label>`).join('')}<button class="heart-pill">Save reusable template ♡</button></form><div class="recordgrid">${templates.map(t=>`<article class="category-row"><div><strong>${esc(t.name)}</strong><small>${esc(t.rhythm)} · target ${t.target}/week</small></div><button class="softbutton" data-action="habit-template-add" data-id="${esc(t.id)}">Start this rhythm</button></article>`).join('')||'<p>No templates saved yet. You can build a rhythm from your own words.</p>'}</div></section><section class="panel"><h2>My active rhythms</h2><div class="recordgrid">${habits.map(h=>{const p=habitWeekProgress(h.data,h.data.logs,day());return `<article class="recordcard"><div class="panelhead"><h3>${esc(h.title)}</h3><span class="tag">${h.status==='Paused'?'Paused':`${p.completed}/${p.target} this week`}</span></div><p>${esc(h.data.rhythm||'Ongoing')} · ${h.data.weekdays?.length?`selected days: ${h.data.weekdays.join(', ')}`:'flexible days'}</p><div class="cardactions"><button class="softbutton" data-action="habit-log" data-id="${esc(h.id)}" ${h.status==='Paused'||(h.data.logs||[]).includes(day())?'disabled':''}>Log today</button><button class="textbutton" data-action="habit-pause" data-id="${esc(h.id)}">${h.status==='Paused'?'Resume':'Pause'} gently</button><button class="textbutton" data-action="edit" data-id="${esc(h.id)}">Edit</button></div></article>`}).join('')||'<p>No rhythms active yet. Start with one that gives you room to be human.</p>'}</div></section>`;}
function goalsPage(){const goals=records('goal'),tasks=records('task');return heading('THE LIFE I’M GROWING INTO','Dreams & <em>milestones.</em>','Keep the reason, the next markers, and the little steps connected.')+`<section class="panel"><div class="panelhead"><h2>My goal hierarchy</h2><button class="heart-pill" data-action="new" data-type="goal">Add a dream ♡</button></div>${goals.map(g=>{const parent=goals.find(x=>x.id===g.data.parentGoalId),linked=tasks.filter(t=>t.data.goalId===g.id||t.links.includes(g.id)),milestones=g.data.milestones||[];return `<article class="panel"><div class="panelhead"><div><h3>${parent?`${esc(parent.title)} → `:''}${esc(g.title)}</h3><p>${esc(g.data.qualitativeProgress||'In my own time')} · ${Number(g.data.progress)||0}%</p></div><button class="textbutton" data-action="edit" data-id="${esc(g.id)}">Edit dream</button></div><form class="goal-update-form formgrid" data-id="${esc(g.id)}"><label>Belongs under<select name="parent"><option value="">No parent dream</option>${goals.filter(x=>x.id!==g.id).map(x=>`<option value="${esc(x.id)}" ${g.data.parentGoalId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>How it feels now<select name="qualitative"><option ${g.data.qualitativeProgress==='Just beginning'?'selected':''}>Just beginning</option><option ${g.data.qualitativeProgress==='Building'?'selected':''}>Building</option><option ${g.data.qualitativeProgress==='Moving steadily'?'selected':''}>Moving steadily</option><option ${g.data.qualitativeProgress==='Paused with care'?'selected':''}>Paused with care</option><option ${g.data.qualitativeProgress==='Celebrating'?'selected':''}>Celebrating</option></select></label><label class="span2">Milestones · one per line<textarea name="milestones" rows="3">${esc(milestones.map(x=>x.title).join('\n'))}</textarea></label><button class="softbutton">Save hierarchy & milestones</button></form><h4>Linked steps · ${linked.length}</h4>${linked.map(t=>`<div class="category-row"><button class="textbutton" data-action="edit" data-id="${esc(t.id)}">${esc(t.title)}</button><span>${esc(t.status)} · ${esc(t.date||'flexible')}</span></div>`).join('')||'<p class="caption">No tasks linked yet.</p>'}<div>${milestones.map((m,i)=>`<button class="softbutton" data-action="goal-milestone" data-id="${esc(g.id)}" data-index="${i}">${m.status==='Done'?'✓':'♡'} ${esc(m.title)}</button>`).join('')}</div></article>`}).join('')||'<p>Start with a dream. It can stay a dream until you choose a next step.</p>'}</section><section class="panel"><span class="tiny-label">ONLY WITH YOUR APPROVAL</span><h2>Turn a dream into a plan</h2><p>Preview the tasks and milestones first. Nothing is created until you approve the exact plan.</p><form id="dream-plan-form" class="formgrid"><label>Saved dream<select name="goal" required>${goals.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('')}</select></label><label>Optional first due date<input name="date" type="date"></label><label class="span2">Possible small steps · one per line<textarea name="steps" rows="4" required placeholder="Choose a first tiny action\nGather what I need"></textarea></label><label class="span2">Milestones · one per line<textarea name="milestones" rows="3" placeholder="First milestone"></textarea></label><button class="heart-pill" ${goals.length?'':'disabled'}>Preview this plan</button></form><div id="dream-plan-preview" role="status">${dreamPlanDraft?`${dreamPlanDraft.steps.length} tasks and ${dreamPlanDraft.milestones.length} milestones ready for review.`:'A dream may stay open ended. Planning is always optional.'}</div></section>`;}
function grimoire(){const writings=listFor('grimoire').filter(r=>!filter||r.title.toLowerCase().includes(filter.toLowerCase())),spreads=records('spread'),manual=records('reading');const positions=selectedSpreadId?spreads.find(x=>x.id===selectedSpreadId)?.data.positions||[]:['What I’m carrying','What needs care','A possible next step'];return heading('THE PRIVATE BOOK OF MY BECOMING','A little <em>practical magic.</em>','Symbols, rituals, reflections. Meaning, in your own words.','ritual')+`<section class="grimoire-banner"><div>${icon('moon')}<span class="tiny-label">THE MOON TOWER</span><h2>As above, <em>so within.</em></h2><p>A record of what you’re learning, releasing, and calling in.</p></div><div class="orbit">✦<span>☾</span>✧</div></section><div class="toolbar"><div class="tabs">${[['all','My pages'],['library','78-card library'],['draw','Reflective draw'],['spreads','My spreads'],['symbols','Search symbols']].map(([id,label])=>`<button class="${tab===id?'selected':''}" data-action="grimoire-tab" data-tab="${id}">${label}</button>`).join('')}</div><button class="softbutton" data-action="new" data-type="reading">Write a reading ♡</button></div>${tab==='library'?`<label class="inline-search">${icon('search')}<input data-tarot-search placeholder="Find a card or suit…" aria-label="Search tarot library"></label><p class="caption">Concise, original reflection notes. Your own meanings belong in your reading journal.</p><div class="tarotlibrary">${tarot.map(c=>`<article class="tarotref" data-card-name="${esc((c.name+' '+c.suit).toLowerCase())}"><span>✦ ${c.suit}</span><h3>${c.name}</h3><p><b>Upright</b> ${c.upright}</p><p><b>Reversed</b> ${c.reversed}</p></article>`).join('')}</div>`:tab==='draw'?`<section class="spreadpanel"><span class="tiny-label">PAUSE · REFLECT · CHOOSE</span><h2>A moment with <em>myself.</em></h2><p>Local random draws for reflection. They do not predict events or outcomes.</p><label>Spread<select id="spread-draw-choice"><option value="">Three-card reflection</option>${spreads.map(x=>`<option value="${esc(x.id)}" ${selectedSpreadId===x.id?'selected':''}>${esc(x.title)} · ${(x.data.positions||[]).length} cards</option>`).join('')}</select></label><div class="spreadcards">${(draw.length?draw:[null,null,null]).map((c,i)=>`<div class="tarotcard ${c?'revealed':''}"><small>${esc(positions[i]||`Card ${i+1}`)}</small>${icon(c?'star':'moon')}<h3>${c?esc(c.name):'✦'}</h3><span>${c?(c.isReversed?'Reversed':'Upright'):'A little mystery'}</span>${c?`<p>${esc(c.isReversed?c.reversed:c.upright)}</p>`:''}</div>`).join('')}</div><div class="centeractions"><button class="heart-pill" data-action="draw">Draw this spread ♡</button>${draw.length?'<button class="softbutton" data-action="save-spread">Keep this reading ↗</button>':''}</div></section><section class="panel"><h2>Write cards manually</h2><p>Enter one card per line: position | card | Upright or Reversed | my meaning. This lets you record a real deck pull or your own selected cards.</p><form id="manual-reading-form" class="formgrid"><label>Reading title<input name="title" required maxlength="180"></label><label>Question (optional)<input name="question" maxlength="500"></label><label class="span2">Cards<textarea name="cards" required placeholder="What I’m carrying | The Star | Upright | What hope means to me" maxlength="6000"></textarea></label><label class="span2">My reflection<textarea name="reflection" maxlength="4000"></textarea></label><button class="heart-pill">Save private reading ♡</button></form>${manual.length?`<h3>Recent readings</h3>${manual.slice(-6).reverse().map(x=>`<div class="category-row"><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">${esc(x.title)}</button><small>${esc(x.date)}</small></div>`).join('')}`:''}</section>`:tab==='spreads'?`<section class="panel"><h2>Make a spread of my own</h2><form id="spread-template-form" class="formgrid"><label>Spread name<input name="title" required maxlength="100"></label><label class="span2">Positions, one per line<textarea name="positions" required placeholder="What I’m noticing; What supports me; A next step"></textarea></label><button class="heart-pill">Save my spread ♡</button></form><div class="recordgrid">${spreads.map(x=>`<article class="recordcard"><h3>${esc(x.title)}</h3><ol>${(x.data.positions||[]).map(p=>`<li>${esc(p)}</li>`).join('')}</ol><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">Edit</button><button class="iconbutton" data-action="trash" data-id="${esc(x.id)}" aria-label="Move ${esc(x.title)} to trash">${icon('trash')}</button></article>`).join('')||'<p>No custom spreads saved. The three-card reflection is ready any time.</p>'}</div></section>`:tab==='symbols'?`<section class="panel"><h2>My searchable symbol dictionary</h2><label class="inline-search">${icon('search')}<input id="grimoire-symbol-search" value="${esc(grimoireSearch)}" placeholder="Search my saved symbols and writing…" aria-label="Search personal symbols"></label><div id="grimoire-symbol-results">${searchGrimoireSymbols(active(store.state),grimoireSearch).map(x=>`<div class="category-row"><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">${esc(x.title)}</button><small>${esc(types[x.type]?.name||x.type)}</small></div>`).join('')||'<p>Private entries stay hidden from this symbol search. Add a personal symbol or correspondence when you want.</p>'}</div><div class="centeractions"><button class="softbutton" data-action="new" data-type="symbol">Add symbol ♡</button><button class="softbutton" data-action="new" data-type="correspondence">Add correspondence ♡</button></div></section>`:`<div class="recordgrid">${writings.length?writings.map(card).join(''):empty('ritual')}</div>`}<p class="caption">Spiritual content is symbolic and personal. It offers no guaranteed predictions, medical guidance, or financial advice.</p>`}
function financeScenarioPage(){const saved=records('note').filter(x=>x.tags.includes('Financial Scenario')).sort((a,b)=>b.date.localeCompare(a.date));const p=financeScenarioPreview;return heading('MONEY, WITH THE ASSUMPTIONS VISIBLE','Possibility <em>lab.</em>','Compare user-entered monthly costs with a one-time move goal. This is arithmetic, not a forecast of future income.')+`<section class="panel"><h2>Build a move-out scenario</h2><p>Enter monthly take-home income only if that is what the number represents. Use zero for costs you have not estimated yet; no income is assumed by DreamHub.</p><form id="move-scenario-form" class="formgrid"><label>Monthly income (USD)<input name="income" inputmode="decimal" value="0" required></label><label>Current cash available (USD)<input name="cash" inputmode="decimal" value="0" required></label><label>One-time move costs (USD)<input name="move" inputmode="decimal" value="0" required></label><label>Housing / rent per month<input name="housing" inputmode="decimal" value="0" required></label><label>Utilities and phone<input name="utilities" inputmode="decimal" value="0" required></label><label>Food and household<input name="food" inputmode="decimal" value="0" required></label><label>Transport<input name="transport" inputmode="decimal" value="0" required></label><label>Debt minimums and other commitments<input name="other" inputmode="decimal" value="0" required></label><label>Monthly saving target (optional)<input name="saving" inputmode="decimal" placeholder="Uses remaining amount if blank"></label><button class="heart-pill">Compare this scenario ♡</button></form>${p?`<section id="finance-scenario-result" class="panel" aria-live="polite"><h3>${esc(p.title)}</h3><div class="money-stats"><div><span>MONTHLY COSTS ENTERED</span><strong>${dollars(p.result.totalMonthlyCosts)}</strong></div><div><span>MONTHLY REMAINDER</span><strong>${dollars(p.result.monthlyRemainder)}</strong><small>${p.result.monthlyRemainder<0?'Costs exceed the entered income':'Before unlisted or changing costs'}</small></div><div><span>ONE-TIME COST LEFT</span><strong>${dollars(p.result.remainingMoveCost)}</strong><small>${p.result.monthsToGoal===null?'No monthly saving amount entered':p.result.monthsToGoal===0?'Covered by cash entered':`About ${p.result.monthsToGoal} months at this saving amount`}</small></div></div><h4>Savings scenarios</h4>${p.result.projectedSavings.map(x=>`<div class="category-row"><span>${x.months} months · after move costs</span><b>${dollars(x.afterMoveCents)}</b></div>`).join('')}<p class="caption">${esc(p.result.assumption)}</p><button class="softbutton" data-action="finance-scenario-save">Save these assumptions</button></section>`:''}</section><section class="panel"><h2>Saved scenarios · ${saved.length}</h2><div class="recordgrid">${saved.map(card).join('')||'<p>No scenarios saved yet.</p>'}</div></section>`;}
function financeWorkflowPanel(){const accounts=records('account'),income=records('plannedIncome'),envelopes=records('envelope'),funds=records('fund');if(tab==='bill'){const bills=records('bill');return `<section class="panel"><h2>Bills and subscriptions · ${esc(month)}</h2><p>Expected obligations are separate from transactions. Mark one paid only after payment occurs; paid rows are logged as expenses and excluded from that month’s recurring forecast.</p>${bills.map(x=>{const dayNum=Number(x.data.dueDay)||Number(x.date?.slice(-2))||1,dueDate=x.data.cadence==='One-time'?(x.date||''):`${month}-${String(Math.min(dayNum,new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).getUTCDate())).padStart(2,'0')}`,period=x.data.cadence==='Yearly'?(x.date||'').slice(0,4)+'-'+String(x.data.annualMonth||x.date?.slice(5,7)||'01').padStart(2,'0'):month,paid=active(store.state).some(t=>t.type==='transaction'&&t.data?.billId===x.id&&t.data?.billPeriod===period&&!t.deletedAt);if(x.data.cadence==='Yearly'&&Number(period.slice(5,7))!==Number(month.slice(5,7)))return '';return `<article class="category-row"><div><strong>${esc(x.title)}</strong><small>${esc(x.data.cadence||'One-time')} · ${dollars(x.data.amount||0)} · ${esc(x.data.category||'Uncategorized')} · due ${esc(dueDate||'date not set')}${x.data.autopay?' · autopay (user marked)':''}</small></div><span class="tag">${paid?'Paid':'Expected'}</span><div class="centeractions"><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">Edit</button>${paid?'':`<button class="softbutton" data-action="bill-paid" data-id="${esc(x.id)}" data-period="${esc(period)}">Record full amount paid</button>`}</div></article>`;}).join('')||'<p>No bills or subscriptions saved. Add one from the transaction toolbar below.</p>'}<p class="caption">Autopay is only a note you enter. DreamHub cannot see accounts, verify payment, or pay a bill.</p></section>`;}if(tab==='accounts')return `<section class="panel"><h2>Manual account snapshots</h2><p>Enter balances you have checked yourself. Snapshots are not linked to a bank and never refresh automatically.</p><form id="finance-account-form" class="formgrid"><label>Account name<input name="title" required maxlength="120"></label><label>Type<select name="kind"><option>Checking</option><option>Savings</option><option>Cash</option><option>Credit card</option><option>Other</option></select></label><label>Balance ($)<input name="balance" inputmode="decimal" required></label><label>Checked on<input name="asOf" type="date" value="${day()}" required></label><button class="heart-pill">Save balance snapshot ♡</button></form><div class="recordgrid">${accounts.map(card).join('')||'<p>No account snapshots yet. Start with a balance you have verified.</p>'}</div></section>`;if(tab==='income')return `<section class="panel"><h2>Confirmed and expected income</h2><p>Log a confirmed deposit when it has actually arrived. Expected income stays separate until you mark it received.</p><form id="finance-income-form" class="formgrid"><label>Source<input name="title" required maxlength="120"></label><label>Amount ($)<input name="amount" inputmode="decimal" required></label><label>Expected date<input name="date" type="date" required></label><label>Confidence<select name="confidence"><option>Expected</option><option>Confirmed</option></select></label><label>Notes<input name="source" maxlength="180" placeholder="Optional source or context"></label><button class="heart-pill">Save income expectation ♡</button></form><div class="recordgrid">${income.map(r=>`<article class="recordcard"><h3>${esc(r.title)}</h3><p>${dollars(r.data.amount||0)} · ${esc(r.data.confidence)} · ${esc(r.date||'Date not set')}</p><small>${esc(r.data.source||'')}</small>${r.data.status!=='Received'?`<button class="softbutton" data-action="income-received" data-id="${esc(r.id)}">Mark received and log ♡</button>`:`<span class="tag">Received</span>`}<button class="textbutton" data-action="edit" data-id="${esc(r.id)}">Edit</button><button class="iconbutton" data-action="trash" data-id="${esc(r.id)}" aria-label="Move ${esc(r.title)} to trash">${icon('trash')}</button></article>`).join('')||'<p>No expected income entered.</p>'}</div></section>`;if(tab==='envelopes')return `<section class="panel"><h2>Category envelopes</h2><p>Set limits for categories you choose. A limit is a planning guardrail; it does not block purchases or move funds.</p><form id="finance-envelope-form" class="formgrid"><label>Envelope name<input name="title" required maxlength="100"></label><label>Category<input name="category" required maxlength="80"></label><label>Limit ($)<input name="limit" inputmode="decimal" required></label><label>Period<select name="period"><option>Monthly</option><option>Weekly</option></select></label><button class="heart-pill">Save envelope ♡</button></form><div class="recordgrid">${envelopes.map(e=>{const from=e.data.period==='Weekly'?(()=>{const d=new Date(day()+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return day(d);})():month+'-01',to=e.data.period==='Weekly'?day(new Date(new Date(from+'T12:00:00').getTime()+6*86400000)):`${month}-${String(new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).getUTCDate()).padStart(2,'0')}`,u=envelopeUsage(e,active(store.state),{from,to});return `<article class="recordcard"><h3>${esc(e.title)}</h3><p>${esc(e.data.category)} · ${esc(e.data.period||'Monthly')}</p><div class="money-stats"><div><span>SPENT</span><strong>${dollars(u.spentCents)}</strong></div><div><span>LIMIT</span><strong>${dollars(u.limitCents)}</strong></div><div><span>REMAINING</span><strong>${dollars(u.remainingCents)}</strong></div></div><div class="progress"><span style="width:${u.percent}%"></span></div><div class="cardactions"><button class="textbutton" data-action="edit" data-id="${esc(e.id)}">Edit</button><button class="iconbutton" data-action="trash" data-id="${esc(e.id)}" aria-label="Move ${esc(e.title)} to trash">${icon('trash')}</button></div></article>`;}).join('')||'<p>No envelopes yet.</p>'}</div></section>`;if(tab==='funds')return `<section class="panel"><h2>Sinking funds</h2><p>Give irregular costs a visible target and contribution plan. Progress is based on amounts you enter.</p><form id="finance-fund-form" class="formgrid"><label>Fund name<input name="title" required maxlength="100"></label><label>Target ($)<input name="target" inputmode="decimal" required></label><label>Saved so far ($)<input name="amount" inputmode="decimal" value="0" required></label><label>Monthly contribution ($)<input name="contribution" inputmode="decimal" value="0" required></label><label>Target date<input name="goalDate" type="date"></label><button class="heart-pill">Save sinking fund ♡</button></form><div class="recordgrid">${funds.map(x=>`<article class="recordcard">${card(x)}<form class="fund-contribution-form" data-id="${esc(x.id)}"><label>Add a contribution ($)<input name="amount" inputmode="decimal" required></label><button class="softbutton">Record contribution</button></form></article>`).join('')||'<p>No sinking funds yet.</p>'}</div></section>`;if(tab==='cashflow'){const scenario=cashflowPreview;return `<section class="panel"><h2>Cashflow and affordability</h2><p>Compare your manual account snapshots, bills, selected income assumptions and one-time costs. Forecasts are estimates from saved inputs.</p><form id="cashflow-form" class="formgrid"><label>Monthly income assumption ($)<input name="income" inputmode="decimal" value="0.00" required></label><label>One-time cost to test ($)<input name="oneTime" inputmode="decimal" value="0.00" required></label><label>Monthly buffer ($)<input name="buffer" inputmode="decimal" value="0.00" required></label><label>From<input name="from" type="date" value="${day()}" required></label><label>Through<input name="to" type="date" value="${day(new Date(Date.now()+90*86400000))}" required></label><label class="checklabel"><input name="includeExpected" type="checkbox" checked> Include expected income in forecast</label><button class="heart-pill">Review cashflow ♡</button></form>${scenario?`<div class="money-stats"><div><span>MONTHLY COSTS ENTERED</span><strong>${dollars(scenario.affordability.monthlyCostsCents)}</strong></div><div><span>MONTHLY REMAINDER</span><strong>${dollars(scenario.affordability.monthlyRemainderCents)}</strong></div><div><span>LOWEST FORECAST CASH</span><strong>${dollars(scenario.forecast.lowestBalance)}</strong><small>${scenario.forecast.firstShortfall?`First below zero: ${esc(scenario.forecast.firstShortfall)}`:'No projected below-zero day in this range'}</small></div></div><h3>Daily forecast</h3><div class="forecast-list">${scenario.forecast.points.filter((p,i)=>i===0||p.events.length||i===scenario.forecast.points.length-1||p.date.endsWith('-01')).map(p=>`<div class="category-row"><span>${esc(p.date)}${p.events.length?` · ${p.events.map(e=>esc(e.label)).join(', ')}`:''}</span><b>${dollars(p.balance)}</b></div>`).join('')}</div><p class="caption">${esc(scenario.affordability.assumption)}</p>`:'<p class="calmempty">Enter your assumptions and select Review cashflow to build a dated forecast.</p>'}</section>`;}if(tab==='statements'){return `<section class="panel"><h2>Statement import review</h2><p>Choose a CSV exported from your bank. DreamHub previews rows, flags likely duplicates and imports only the rows you select. No bank login or credentials are requested.</p><label>CSV statement<input id="statement-input" type="file" accept=".csv,text/csv"></label>${statementImportRows.length?`<p>${statementImportRows.filter(x=>x.status==='match').length} suggested matches · ${statementImportRows.filter(x=>x.status==='unmatched').length} new rows · ${statementImportRows.filter(x=>x.status==='ambiguous'||x.status==='already-imported'||x.status==='duplicate-in-file').length} held for review.</p><div class="statement-preview">${statementImportRows.map(x=>`<label class="category-row"><input type="checkbox" data-statement-row="${x.index}" ${['ambiguous','already-imported','duplicate-in-file'].includes(x.status)?'disabled':''} ${x.selected?'checked':''}><span>${esc(x.date)} · ${esc(x.description)} · ${x.direction==='Income'?'+':'−'}${dollars(x.amount)}${x.account?' · '+esc(x.account):''}</span>${x.status==='match'?`<b>Match: ${esc(x.matches[0]?.title||'saved transaction')}</b>`:x.status==='ambiguous'?'<b>Ambiguous: choose manually in your ledger</b>':x.status==='already-imported'?'<b>Already imported</b>':x.status==='duplicate-in-file'?'<b>Duplicate within file</b>':'<b>New transaction</b>'}</label>`).join('')}</div><button class="heart-pill" data-action="statement-import-approved">Import selected rows ♡</button>`:'<p class="calmempty">Choose a statement file to preview rows here.</p>'}<p class="caption">Exact amount and direction plus a small posting-date window suggest possible matches. Ambiguous rows stay unchecked. Selected matches are marked reconciled; selected unmatched rows are imported and marked reconciled. No bank connection is made.</p></section>`;}return ''}
function treasury(){const all=active(store.state),t=totals(all,month),plan=store.state.budgetPlans[month]?.limit||0, bills=records('bill'),debts=records('debt'),vaults=records('saving'),monthlyBills=bills.reduce((n,r)=>n+(r.data.cadence==='Monthly'?(r.data.amount||0):r.data.cadence==='Yearly'?Math.round((r.data.amount||0)/12):0),0);return heading('MY WEALTH ERA · FREEDOM BY 30','The money <em>sanctuary.</em>','A life of freedom is built one conscious dollar at a time. ♡','transaction')+`<div class="toolbar"><div class="tabs">${[['all','Overview'],['payday','Payday ritual'],['transaction','Transactions'],['bill','Bills'],['debt','Debt lab'],['saving','Savings'],['invest','Investing'],['accounts','Accounts'],['income','Expected income'],['envelopes','Envelopes'],['funds','Sinking funds'],['cashflow','Cashflow'],['statements','Statements']].map(([id,label])=>`<button class="${tab===id?'selected':''}" data-action="money-tab" data-tab="${id}">${label}</button>`).join('')}</div><label class="monthfield">Month <input type="month" id="money-month" value="${month}"></label></div><div class="money-stats"><div><span>PERSONAL INCOME LOGGED</span><strong>${dollars(t.income)}</strong><small>Recorded, not bank-verified</small></div><div><span>PERSONAL SPENDING LOGGED</span><strong>${dollars(t.expense)}</strong><small>Transactions entered this month</small></div><div><span>MONTHLY BILLS ON FILE</span><strong>${dollars(monthlyBills)}</strong><small>Check which bills remain unpaid</small></div></div>
${financeWorkflowPanel()}
${tab==='all'?moneyPolicyPanel():''}
${tab==='all'||tab==='payday'?`<section class="panel"><span class="tiny-label">THE PAYDAY RITUAL ♡</span><h2>Give every paycheck & tip a purpose</h2><p>Enter what actually arrived. Reserve outstanding essentials, minimum debt payments, taxes and your safety buffer first. Everything else gets a beautiful assignment. The plan never moves money.</p><form id="payday-form" class="formgrid"><label>Income received ($)<input required name="income" inputmode="decimal" placeholder="150.00"></label><label>Source<select name="source"><option>Paycheck</option><option>Tips</option><option>Studio owner pay</option><option>Other</option></select></label><label>Still-unpaid essential bills ($)<input required name="essentials" inputmode="decimal" value="0.00"></label><label>Minimum debt payments still due ($)<input required name="minimums" inputmode="decimal" value="0.00"></label><label>Tax reserve needed ($)<input required name="taxes" inputmode="decimal" value="0.00"></label><label>Cash safety buffer ($)<input required name="buffer" inputmode="decimal" value="0.00"></label><button class="heart-pill" type="submit">Plan my payday ♡</button></form><div id="payday-result" role="status"></div><p class="caption">All figures are editable. Enter remaining commitments for the period, not bills you've already paid. Studio gross receipts need business expenses and applicable tax reserves before they become owner pay. Allocations are suggestions, not actual transfers.</p></section>`:''}
${tab==='all'?`<div class="lowergrid twocol"><section class="panel"><h2>My financial foundations</h2><p>${bills.length} bill records · ${debts.length} debt records · ${vaults.length} savings vaults.</p><p>Build a $1,000 starter emergency reserve, work towards under 30% credit utilization, then zero interest-bearing card balances. Grow your apartment, car, travel and house funds together as income stabilizes.</p><button class="softbutton" data-action="money-starters">Add editable starter vaults & known bills ♡</button><p class="caption">Adds only missing entries. The starter figures are historical or aspirational; review before using them. No account balances are prefilled.</p></section><section class="panel"><h2>A little spending plan</h2><form id="budget-form"><label>Personal spending limit for ${month}<input name="limit" inputmode="decimal" value="${(plan/100).toFixed(2)}" required></label><button class="heart-pill">Save my plan ♡</button></form><div class="progress"><span style="width:${plan?Math.min(100,t.expense/plan*100):0}%"></span></div><p>${plan?dollars(plan-t.expense)+' remaining against entered limit.':'Set a limit to see your budget progress.'}</p></section></div>`:''}
${tab==='debt'?`<section class="panel"><h2>Credit freedom at 30% · then zero ♡</h2><form id="utilization-form" class="inlineform"><label>Card balance ($)<input name="balance" inputmode="decimal" required></label><label>Credit limit ($)<input name="limit" inputmode="decimal" required></label><button class="heart-pill">Calculate my milestone</button></form><div id="utilization-result" role="status"></div><p class="caption">Calculated separately per card. Verify the balance and credit limit; a 30% target is a milestone, not guaranteed credit-score improvement.</p><h2>Debt payoff scenario</h2><form id="debt-form" class="inlineform"><label>Balance ($)<input name="balance" inputmode="decimal" required></label><label>APR (%)<input name="apr" type="number" min="0" max="100" step=".01" required></label><label>Payment ($/month)<input name="payment" inputmode="decimal" required></label><button class="heart-pill">Explore my plan ♡</button></form><div id="debt-result" role="status"></div></section>`:''}
${tab==='invest'?`<section class="panel"><span class="tiny-label">A LONG-TERM MONEY GARDEN</span><h2>Plant for the future</h2><p>Build a safety net first, then consider retirement accounts, diversified index funds and steady automatic contributions. Keep short-term apartment and car savings out of volatile investments.</p><form id="investment-form" class="inlineform"><label>Monthly investment ($)<input name="monthly" value="100.00" inputmode="decimal" required></label><label>Years<input name="years" type="number" value="10" min="1" max="50" required></label><label>Assumed annual return (%)<input name="rate" type="number" value="7" min="0" max="15" step=".1" required></label><button class="heart-pill">See the possibility ♡</button></form><div id="investment-result" role="status"></div><p class="caption">Illustration only; not a guarantee. Excludes inflation, taxes and fees. DreamHub does not trade securities.</p></section>`:''}
<div class="toolbar"><h2>${tab==='all'?'My money pages':({bill:'Bills & subscriptions',debt:'My debt records',saving:'Savings in bloom',transaction:'Transactions',payday:'Income journal',invest:'My investment notes'}[tab])}</h2><div class="centeractions">${(tab==='all'?['bill','debt','saving']:['bill','debt','saving','transaction'].includes(tab)?[tab]:['transaction']).map(type=>`<button class="softbutton" data-action="new" data-type="${type}">${icon('plus')} ${types[type].name}</button>`).join('')}</div></div><div class="recordgrid">${listFor('treasury').filter(r=>(tab==='all'||tab==='payday'||tab==='invest'||r.type===tab)&&(r.type!=='transaction'||r.date.startsWith(month))).map(card).join('')||empty('transaction')}</div><p class="caption">Private data stays in your DreamHub browser storage unless you explicitly activate private cloud sync. Never store account credentials in entries. No money moves through DreamHub.</p>`;}
function reminderPanel(){const overdue=overdueItems(active(store.state),day()),soon=upcomingReminders(active(store.state),new Date(),120);return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">MY GENTLE REMINDER DESK</span><h2>What's coming up?</h2></div><span class="tag">${overdue.length} overdue</span></div><p>${soon.length} items within the next two hours. ${overdue.length} dated tasks, bills or applications need review.</p>${soon.slice(0,5).map(x=>`<div class="category-row"><span>${esc(x.title)}</span><small>${new Date(x.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small></div>`).join('')}<button class="softbutton" data-action="reminder-optin">Enable browser reminders while DreamHub is open</button><p class="caption">Requires browser permission. Only while this page remains open; not push notifications or a background automation service. Untimed entries use 9 AM as a planning reminder, not a confirmed appointment time.</p></section>`;}
function schedulerStudio(){const date=selectedDate||day(),today=active(store.state).filter(r=>r.type==='event'&&r.date===date&&r.tags?.includes('Day Architect')),movement=movementForDate(date);return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">CONNECTED LIFE SCHEDULER ♡</span><h2>Time blocks that respect my actual appointments</h2></div><span class="tag">${today.length} saved blocks</span></div><form id="scheduler-form" class="formgrid"><label>Available from<input type="time" name="start" value="10:00" required></label><label>Until<input type="time" name="end" value="19:00" required></label><label>My energy<select name="energy"><option value="low">Low energy</option><option value="steady" selected>Steady</option><option value="high">High energy</option></select></label><label>Minutes between blocks<input type="number" name="buffer" min="0" max="60" value="10"></label><label class="checklabel span2"><input type="checkbox" name="workout" checked> Include ${esc(movement.name)} when it fits</label><button class="heart-pill">Preview my time blocks ♡</button></form><div id="scheduler-preview" role="status"><p class="caption">The planner checks existing timed events and open tasks, suggests focus windows, and flags overlaps. Preview first; saving is always your choice.</p></div><p class="caption">Saved blocks become editable DreamHub calendar events. This does not write to Google Calendar, send notifications, or run when the site is closed.</p></section>`;}
function movementMetrics(){const keys=[['weight','Weight (lb)'],['neck','Neck (in)'],['leftArm','Left arm (in)'],['rightArm','Right arm (in)'],['bust','Bust (in)'],['waist','Natural waist (in)'],['lowerWaist','Lower waist (in)'],['hips','Hips (in)'],['leftThigh','Left thigh (in)'],['rightThigh','Right thigh (in)'],['leftCalf','Left calf (in)'],['rightCalf','Right calf (in)']],saved=active(store.state).filter(r=>r.type==='note'&&r.tags?.includes('Private body measurements')).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">PRIVATE PROGRESS ARCHIVE</span><h2>Measurements & trends</h2></div><span class="tag">${saved.length} check-ins</span></div><p>Optional. Track strength and how you feel, or record measurements only when useful. These entries stay in your own DreamHub storage and are not committed to GitHub.</p><form id="measurement-form" class="formgrid"><label>Date<input type="date" name="date" value="${day()}" required></label>${keys.map(([k,label])=>`<label>${label}<input type="number" min="0" max="1000" step="0.1" name="${k}" placeholder="Optional"></label>`).join('')}<label class="span2">Notes<textarea name="notes" maxlength="500" placeholder="Energy, strength, clothes fit, progress that isn't a number…"></textarea></label><button class="heart-pill">Save private check-in ♡</button></form><label>Trend to review<select id="metric-select">${keys.map(([k,label])=>`<option value="${k}">${label}</option>`).join('')}</select></label><div id="metric-trend" role="status">${metricTrend('weight')}</div><div class="centeractions"><button class="softbutton" data-action="movement-schedule">Add the next 7 workout sessions to my planner</button></div><p class="caption">The weekly routine is a starting template, not a required schedule. Review before adding; duplicate workouts are skipped.</p></section>`;}
function metricTrend(key){const series=measurementSeries(active(store.state),key);if(!series.length)return '<p class="calmempty">No measurements for this metric yet.</p>';const min=Math.min(...series.map(p=>p.value)),max=Math.max(...series.map(p=>p.value)),range=Math.max(1,max-min),points=series.slice(-20);return `<svg viewBox="0 0 340 120" width="100%" height="120" role="img" aria-label="Measurement trend for ${esc(key)}"><polyline fill="none" stroke="currentColor" stroke-width="3" points="${points.map((p,i)=>`${20+i*300/Math.max(1,points.length-1)},${100-(p.value-min)/range*80}`).join(' ')}"/></svg><p class="caption">${points.length} entries · first ${points[0].value} · latest ${points.at(-1).value}. A chart describes change, not health or worth.</p>`;}
function brainDesk(){const date=selectedDate||day(),items=active(store.state),todays=items.filter(r=>r.date===date&&['event','bill','application'].includes(r.type)),overdue=items.filter(r=>r.type==='task'&&r.status!=='Done'&&r.date<date),plan=planDay(items,date,'steady',180);return `<section class="panel" id="brain-desk"><div class="panelhead"><div><span class="tiny-label">MY EXTERNAL BRAIN · THE DAY ARCHITECT ♡</span><h2>Tell my brain what matters today</h2></div><a href="#inbox" class="textlink">Life inbox ↗</a></div><p>Capture once, choose a realistic day, and leave space between things. No shame, no streaks, no hidden scheduling.</p><form id="brain-capture-form" class="inlineform"><label class="span2">What's on my mind?<input name="thought" required maxlength="240" placeholder="Call the dentist, buy Freyja's supplies, follow up with a client…"></label><button class="heart-pill">Catch this thought ♡</button></form><div class="lowergrid twocol"><div><h3>My day, gently designed</h3><form id="brain-plan-form" class="inlineform"><label>Energy<select name="energy"><option value="low">Low energy</option><option value="steady" selected>Steady</option><option value="high">Ready to focus</option></select></label><label>Time I can give (minutes)<input name="minutes" type="number" min="15" max="720" value="180"></label><button class="softbutton">Make my day plan ♡</button></form><div id="brain-plan-result" role="status">${plan.blocks.filter(b=>b.kind==='focus').length} possible focus tasks · ${plan.appointments.length} appointments today. Adjust energy and time for a detailed plan.</div></div><div><h3>Things needing my attention</h3><p>${todays.length} dated commitments · ${overdue.length} open tasks dated before today.</p><div class="centeractions"><button class="softbutton" data-action="new" data-type="task" data-date="${date}">Add a tiny task</button><button class="softbutton" data-action="new" data-type="event" data-date="${date}">Add an appointment</button></div><p class="caption">Plans are suggestions, not scheduled calendar events. Your saved tasks stay intact.</p></div></div></section>`;}
function movementGarden(){const date=selectedDate||day(),session=movementForDate(date),logs=active(store.state).filter(r=>r.type==='habit'&&r.tags?.includes('Movement Garden')&&r.date===date);return heading('MY BODY, MY RHYTHM','The movement <em>garden.</em>','Strength, stamina, and care—at my pace.','habit')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">TODAY’S MOVEMENT ♡</span><h2>${esc(session.name)}</h2></div><span class="tag">${session.minutes?session.minutes+' min':'Rest'}</span></div><p>Begin with 5 minutes of comfortable warm-up. Rest 60–90 seconds between sets, move with control, and exhale through the harder part. Stop if you feel dizzy, faint, or have chest pain.</p>${session.exercises.map(([name,reps])=>`<div class="category-row"><span>${esc(name)}${exerciseSwaps[name]?`<small>Swap: ${esc(exerciseSwaps[name].join(' / '))}</small>`:''}</span><strong>${esc(reps)}</strong></div>`).join('')}<form id="movement-log-form" class="formgrid"><label>How did it go?<select name="result"><option value="complete">Completed</option><option value="partial">Shorter session</option><option value="rest">Rested instead</option></select></label><label>Effort<select name="effort"><option value="steady">Comfortable challenge</option><option value="easy">Felt easy</option><option value="hard">Felt hard</option></select></label><label class="span2">Notes (optional)<input name="notes" maxlength="400" placeholder="Reps, weights, energy, how I felt…"></label><button class="heart-pill">Save my movement ♡</button></form><p class="caption">${logs.length} session log(s) for this day. Records are stored in your DreamHub data, not GitHub.</p></section><section class="panel"><h2>My weekly movement rhythm</h2><div class="category-row"><span>Monday / Friday</span><strong>Glutes + legs</strong></div><div class="category-row"><span>Wednesday</span><strong>Upper + core</strong></div><div class="category-row"><span>Tuesday / Thursday</span><strong>Walk + mobility</strong></div><div class="category-row"><span>Saturday</span><strong>Fun movement / class</strong></div><div class="category-row"><span>Sunday</span><strong>Rest</strong></div><p class="caption">Start with one or two sets if returning to exercise. Increase reps or resistance gradually, never both at once. No exercise can choose where body fat is lost; strength can develop muscle while overall body composition changes.</p></section>`+movementMetrics();}
function recurrenceManager(){const rules=store.state.settings.recurrenceRules||[],today=day(),to=new Date(today+'T12:00:00Z');to.setUTCDate(to.getUTCDate()+30);const horizon=to.toISOString().slice(0,10),proposals=rules.flatMap(rule=>recurrenceOccurrences(rule,{from:today,to:horizon,timezone:rule.timezone||store.state.settings.timezone}).map(x=>({...x,title:rule.title,kind:rule.kind||'task',paused:rule.paused}))).filter(x=>!x.paused&&!active(store.state).some(r=>r.data?.recurrenceOccurrenceId===`${x.ruleId}:${x.date}`));return `<section class="panel"><span class="tiny-label">REPEAT WITH ROOM TO PAUSE</span><h2>Recurrence rules</h2><p>Rules create dated proposals in your selected timezone. Skip an occurrence or pause a rule any time. Review and approve each event or task.</p><form id="recurrence-rule-form" class="formgrid"><label>What repeats?<input name="title" maxlength="160" required></label><label>First date<input type="date" name="start" value="${today}" required></label><label>Frequency<select name="frequency"><option>daily</option><option selected>weekly</option><option>monthly</option></select></label><label>Every N periods<input name="interval" type="number" min="1" max="365" value="1"></label><label>At local time (optional)<input name="time" type="time"></label><label>Repeated daylight-saving time<select name="timeFold"><option value="earlier">Earlier clock time</option><option value="later">Later clock time</option></select></label><label>Timezone<input name="timezone" value="${esc(store.state.settings.timezone||'America/Detroit')}" placeholder="America/Detroit"></label><label>Create as<select name="kind"><option value="task">Task</option><option value="event">Calendar event</option></select></label><fieldset class="span2"><legend>Weekly days, when weekly</legend>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((x,i)=>`<label class="checklabel"><input type="checkbox" name="weekday" value="${i}">${x}</label>`).join('')}</fieldset><button class="heart-pill">Save recurrence rule ♡</button></form>${rules.map(rule=>`<article class="category-row"><div><strong>${esc(rule.title)}</strong><small>${esc(rule.frequency)} · every ${rule.interval} · ${esc(rule.time||'all day')} · ${esc(rule.timezone||'')}</small></div><button class="softbutton" data-action="recurrence-toggle" data-id="${esc(rule.id)}">${rule.paused?'Resume':'Pause'}</button><button class="textbutton" data-action="recurrence-delete" data-id="${esc(rule.id)}">Remove</button></article>`).join('')||'<p>No recurrence rules yet.</p>'}<h3>Next 30 days · review before creating</h3>${proposals.slice(0,40).map(x=>`<article class="category-row"><div><strong>${esc(x.date)} · ${esc(x.title)}</strong><small>${esc(x.time||'All day')} ${esc(x.timezone)}${x.dst?` · ${esc(x.dst)} local time needs review`:''}</small></div>${x.dst?'':`<button class="softbutton" data-action="recurrence-occurrence" data-rule="${esc(x.ruleId)}" data-date="${esc(x.date)}">Approve ${esc(x.kind)}</button>`}<button class="textbutton" data-action="recurrence-skip" data-rule="${esc(x.ruleId)}" data-date="${esc(x.date)}">Skip once</button></article>`).join('')||'<p>No occurrences in the next month.</p>'}</section>`;}
function calendar(){const [y,m]=month.split('-').map(Number),start=new Date(y,m-1,1),count=new Date(y,m,0).getDate(),offset=(start.getDay()+6)%7,entries=active(store.state).filter(r=>['event','task','bill','application'].includes(r.type)),view=calendarView,anchor=view==='month'?`${month}-01`:selectedDate||day(),range=calendarRange(view,anchor),zone=store.state.settings.timezone||'America/Detroit',occurrences=calendarOccurrences(active(store.state),{...range,timezone:zone}),conflicts=calendarConflicts(occurrences);const days=view==='day'?[range.from]:Array.from({length:7},(_,i)=>{const d=new Date(range.from+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10);});const schedule=view==='month'?`<div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="calendarblank"></div>').join('')}${Array.from({length:count},(_,i)=>{const date=`${month}-${String(i+1).padStart(2,'0')}`,rs=calendarItems(active(store.state),date),timed=occurrences.filter(x=>x.date===date);return `<div class="calendarday ${date===day()?'today':''}"><button class="daynumber" data-action="calendar-date" data-date="${date}" aria-label="Add event for ${date}">${i+1}</button>${timed.slice(0,3).map(r=>`<button class="calendarentry" data-action="${r.type==='task'?'edit':'edit'}" data-id="${esc(r.id)}">${esc(r.time||'')} ${esc(r.title)}${r.dst?' · time review':''}</button>`).join('')}${rs.filter(r=>r.source==='computed').slice(0,1).map(r=>`<a class="calendarentry" href="#sanctuary">♡ ${esc(r.title)}</a>`).join('')}${timed.length>3?`<button class="textbutton" data-action="calendar-agenda" data-date="${date}">+${timed.length-3} more</button>`:''}</div>`}).join('')}</div>`:`<section class="panel agenda">${days.map(date=>`<article class="agenda-day"><h3>${new Date(date+'T12:00:00Z').toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',timeZone:'UTC'})}</h3><button class="textbutton" data-action="calendar-date" data-date="${date}">Add an event</button>${occurrences.filter(x=>x.date===date).map(r=>`<div class="agenda-row"><span>${esc(r.time||'All day')}<small>${esc(r.timezone)}${r.dst?' · needs time review':''}</small></span><button class="textbutton" data-action="edit" data-id="${esc(r.id)}"><strong>${esc(r.title)}</strong></button><span class="tag">${esc(r.type)}${r.location?' · '+esc(r.location):''}</span></div>`).join('')||'<p class="caption">No saved items this day.</p>'}</article>`).join('')}</section>`;return heading('THE TIME GARDEN','My enchanted <em>calendar.</em>','Plan by day, week, or month. Local-time events are checked in the timezone you choose.','event')+`<section class="panel"><span class="tiny-label">YOUR CALENDAR TIMEZONE</span><form id="calendar-timezone-form" class="inlineform"><label>Display timezone (IANA)<input name="timezone" value="${esc(zone)}" placeholder="America/Detroit" required></label><button class="softbutton">Save timezone</button></form><p class="caption">Saved timed events can keep their own timezone. Times with missing or repeated daylight-saving clock times are flagged for review; no time is silently adjusted.</p></section><section class="panel"><span class="tiny-label">HEALTHCARE PREPARATION ♡</span><h2>Appointment companion</h2><p>Choose Healthcare as an event category to get preparation, transportation and follow-up steps. These stay private in your saved records.</p>${entries.filter(r=>r.type==='event'&&r.data?.category==='Healthcare').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,8).map(r=>`<article class="panel"><h3>${esc(r.title)} · ${esc(r.date)}</h3><p>${appointmentCapacity(entries,r.date).count} healthcare appointments scheduled this week (preferred maximum: 2).</p>${healthcareWorkflow(active(store.state),r).map(step=>`<button class="softbutton" data-action="health-step" data-id="${esc(r.id)}" data-step="${esc(step.key)}">${step.done?'✓':'♡'} ${esc(step.title)}</button>`).join('')}</article>`).join('')||'<p>No healthcare appointments entered yet.</p>'}</section>${brainDesk()}${schedulerStudio()}${reminderPanel()}<div class="toolbar"><div class="centeractions"><button class="iconbutton" data-action="calendar-nav" data-step="-1" aria-label="Previous ${view}">←</button><h2>${view==='month'?start.toLocaleString('en',{month:'long',year:'numeric'}):`${range.from} – ${range.to}`}</h2><button class="iconbutton" data-action="calendar-nav" data-step="1" aria-label="Next ${view}">→</button></div><div class="tabs">${['day','week','month'].map(x=>`<button class="${view===x?'selected':''}" data-action="calendar-view" data-view="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><button class="softbutton" data-action="ics">${icon('calendar')} Export events (.ics)</button></div>${conflicts.length?`<section class="panel warning"><strong>Conflict review · ${conflicts.length}</strong>${conflicts.map(x=>`<p>${esc(x.date)} · ${x.reason==='overlap'?x.ids.map(id=>esc(active(store.state).find(r=>r.id===id)?.title||id)).join(' overlaps '):`${esc(active(store.state).find(r=>r.id===x.ids[0])?.title||x.ids[0])} has a ${esc(x.reason)} local time in ${esc(zone)}`}</p>`).join('')}</section>`:''}${schedule}<section class="panel agenda"><div class="panelhead"><h2>${selectedDate?'On '+selectedDate:view==='month'?'This month’s little plans':view==='week'?'This week’s plans':'Today’s plans'}</h2><span class="caption">${esc(zone)} · conflicts are shown for review</span></div>${occurrences.map(r=>`<button class="agenda-row" data-action="edit" data-id="${esc(r.id)}"><span>${esc(r.date)}<small>${esc(r.time||'All day')}</small></span><strong>${esc(r.title)}</strong><span class="tag">${esc(r.type)}</span></button>`).join('')||'<p class="calmempty">Your calendar has breathing room. Choose a date to make a plan.</p>'}</section><section class="panel"><h2>Bring in an .ics calendar</h2><p>Preview the file and select the events you want to add. External IDs are checked to avoid duplicates.</p><label>Choose a calendar file<input id="ics-input" type="file" accept=".ics,text/calendar"></label><div id="ics-import-review">${calendarImportPreview.map(x=>`<label class="checklabel"><input type="checkbox" data-ics-event="${esc(x.externalId)}" ${x.duplicate?'disabled':''}>${esc(x.title)} · ${esc(x.date)}${x.time?' · '+esc(x.time):''}${x.duplicate?' · already imported':''}</label>`).join('')} ${calendarImportPreview.length?'<button class="softbutton" data-action="ics-import-approved">Add selected events</button>':''}</div></section>${recurrenceManager()}`}

function focus(){const timer=store.state.timer,linked=records('task').find(r=>r.id===(timer?.taskId||focusedTask)),readiness=linked?taskReadiness(linked,active(store.state)):null;return heading('THE REST CAN WAIT','A pocket of <em>possibility.</em>','Make yourself comfortable. One little thing at a time.')+`<div class="focusgrid"><section class="focus-room"><span class="tiny-label">A LITTLE SPACE TO BEGIN</span><div class="clock-orbit"><span>✧</span><div class="focusclock" data-clock>${timerText()}</div><span>♡</span></div><div class="duration-pills">${[5,15,25,45].map(n=>`<button data-action="duration" data-minutes="${n}" class="${(timer?.duration||25)===n?'selected':''}">${n} min</button>`).join('')}</div><label class="focus-select">What am I giving my attention to?<select id="focus-task"><option value="">Just a little space to focus</option>${records('task').filter(r=>r.status!=='Done').map(r=>`<option value="${r.id}" ${(r.id===(timer?.taskId||focusedTask))?'selected':''}>${esc(r.title)}${!taskReadiness(r,active(store.state)).ready?' · waiting on a step':''}</option>`).join('')}</select></label>${linked?`<article class="category-row"><div><strong>${esc(linked.title)}</strong><small>${esc(linked.data.nextAction||'One possible next action')}${linked.data.location?' · '+esc(linked.data.location):''}</small><small>${readiness.ready?'Ready to work':`Waiting on ${readiness.pending.map(x=>x.title).join(', ')||'a linked task'}`}</small></div><button class="textbutton" data-action="edit" data-id="${esc(linked.id)}">Open task</button></article>`:''}<div class="centeractions"><button class="heart-pill" data-action="focus-start">${icon('heart')} ${timer?.running?'Pause gently':'Begin my session'}</button><button class="softbutton" data-action="focus-break">Take a 5-minute break</button><button class="softbutton" data-action="focus-reset">Reset</button></div><div class="centeractions"><button class="softbutton" data-action="focus-sound-toggle">Local completion sound: ${store.state.settings.focusSound?'On':'Off'}</button><button class="textbutton" data-action="focus-tone">Preview sound</button></div><p class="caption">Timer survives refresh on this device. A session never marks its task complete. Sound is generated locally only when enabled. No closed-browser notifications.</p></section><div><section class="panel"><span class="tiny-label">PUT IT DOWN FOR A MOMENT</span><h2>The distraction parking lot</h2><p>That thought can wait here while you do your thing.</p><form id="parking-form"><label class="sr-only" for="parking">A distracting thought</label><textarea id="parking" name="thought" placeholder="Oh, and also…" required></textarea><button class="softbutton">Park this thought ♡</button></form>${records('note').filter(x=>x.tags.includes('Focus parking lot')).slice(-8).reverse().map(x=>`<article class="category-row"><span>${esc(x.title)}</span><button class="textbutton" data-action="edit" data-id="${esc(x.id)}">Review</button></article>`).join('')}</section><section class="panel sessionlist"><h2>Little pockets, collected</h2>${store.state.sessions.slice(-20).reverse().map(x=>`<div class="category-row"><span>${new Date(x.at).toLocaleDateString()}<small>${esc(x.kind==='break'?'Rest break':x.title)}${x.taskId?' · linked to a task':''}</small></span><b>${x.minutes} min</b></div>`).join('')||'<p class="calmempty">Your finished sessions will land here.<br>No streaks to keep up with.</p>'}</section></div></div>`}
function estate(){const rooms=estateRoutes(groups).filter(r=>!store.state.settings.hidden.includes(r.id));return heading('ALL MY WORLDS, CONNECTED','The <em>dream estate.</em>','An accessible 2D map of every room. Use Tab or arrow keys to wander, or open the plain dashboard at any time.')+`<a href="#home" class="softbutton estate-escape">${icon('home')} Back to the plain dashboard</a><section class="estate-scene"><div class="estate-sky" aria-hidden="true"><span>✦</span><span>☾</span><span>✧</span></div><div class="estate-title">Arabella’s <em>ever after</em></div><p id="estate-help">Choose a room. On a keyboard, use arrow keys to move between rooms and Enter to open one.</p><nav class="estate-rooms" aria-label="Dream Estate rooms" aria-describedby="estate-help">${rooms.map((r,i)=>`<a href="#${esc(r.id)}" class="estate-room" data-estate-room data-index="${i}" aria-keyshortcuts="ArrowUp ArrowDown ArrowLeft ArrowRight"><span class="estate-roof" aria-hidden="true"></span><div class="estate-window" aria-hidden="true">${icon(r.icon)}</div><h2>${esc(r.label)}</h2><small>${esc(r.group)} · Open room ↗</small></a>`).join('')}</nav><p>A whole life. A little universe. All yours. ♡</p></section>`;}
function rulePage(){const rules=store.state.rules.filter(r=>r.automationVersion===1),conditionText=r=>(r.conditions||[]).map(c=>`${c.field} ${c.operator} ${c.value}`).join(r.conditionMode==='any'?' OR ':' AND ')||'No extra conditions';return heading('SMALL HELP, ON MY TERMS','The automation <em>atelier.</em>','Build transparent local rules, dry-run the result, then approve each action yourself.')+`<section class="panel"><h2>Write a little rule</h2><p>Choose a saved-data trigger, optional conditions, a local action and quiet hours. Rules stay off until enabled.</p><form id="automation-rule-form" class="formgrid"><label class="span2">Rule name<input name="name" required maxlength="100" placeholder="Interview follow-up"></label><label class="span2">WHEN<select name="trigger">${automationTriggers.map(x=>`<option value="${x.id}">${esc(x.label)} · ${esc(x.sourceType)}</option>`).join('')}</select></label><label class="span2">THEN<select name="actionType">${automationActions.map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('')}</select></label><label>Match conditions<select name="conditionMode"><option value="all">Match all (AND)</option><option value="any">Match any (OR)</option></select></label><label>Maximum approvals per day<input type="number" name="maxRunsPerDay" min="1" max="25" value="5"></label><label class="span2">IF · one condition per line: field | equals/contains | value<textarea name="conditions" placeholder="status | equals | Applied
priority | equals | Important
tag | contains | career"></textarea><small>Supported fields: status, category, priority, energy, type, tag, favorite. Leave blank to match all trigger records.</small></label><label>Follow-up delay (days)<input type="number" name="delayDays" min="1" max="90" value="7"></label><label>Due window (days)<input type="number" name="withinDays" min="1" max="30" value="3"></label><label>Quiet hours start<input type="time" name="quietStart"></label><label>Quiet hours end<input type="time" name="quietEnd"></label><label class="checklabel"><input type="checkbox" name="enabled">Enable this rule</label><p class="caption span2">Actions create a DreamHub task, reflection page or inbox note after approval. Preview runs are logged; they create no life record. Quiet hours use your saved timezone. No email, purchase, payment, calendar booking, remote edit, or background schedule is enabled.</p><button class="heart-pill">Save my rule ♡</button></form></section><section class="panel"><div class="panelhead"><h2>My rules</h2><span class="tag">${rules.length} saved</span></div>${rules.map(r=>`<article class="category-row"><div><strong>${esc(r.name)}</strong><small>${esc(automationTriggers.find(t=>t.id===r.trigger)?.label||r.trigger)} · ${esc(automationActions.find(x=>x.id===r.actionType)?.label||'Local action')} · ${r.enabled?'On':'Off'}</small><small>${esc(conditionText(r))} · cap ${r.maxRunsPerDay}/day · quiet ${esc(r.quietStart||'off')}–${esc(r.quietEnd||'off')}</small>${quietHoursActive(r)?'<small class="warning">Quiet hours are active.</small>':''}</div><div><button class="softbutton" data-action="automation-toggle" data-id="${esc(r.id)}">${r.enabled?'Pause':'Enable'}</button><button class="textbutton" data-action="automation-preview" data-id="${esc(r.id)}">Preview this rule</button></div></article>`).join('')||'<p>No custom rules yet. Start with one small helper.</p>'}<label>Low-energy preview<select id="automation-energy"><option>Low</option><option>Medium</option><option>High</option></select></label><button class="heart-pill" data-action="automation-preview">Preview enabled rules</button></section>${automationPreview.length?`<section class="panel"><div class="panelhead"><h2>Review suggestions</h2><span class="tag">${automationPreview.length} waiting</span></div>${automationPreview.map(p=>`<article class="recordcard"><small>${esc(p.ruleName)} · ${esc(p.sourceType)} · ${esc(p.date)}</small><h3>${esc(p.title)}</h3><p>${esc(p.action)}</p><div class="cardactions"><button class="heart-pill" data-action="automation-proposal" data-decision="approve" data-proposal="${esc(p.proposalId)}">Approve ${esc(automationActions.find(x=>x.id===p.actionType)?.label||'action').replace(/^(Create a linked |Prepare a |Add a )/,'')}</button><button class="softbutton" data-action="automation-proposal" data-decision="dismiss" data-proposal="${esc(p.proposalId)}">Dismiss</button></div></article>`).join('')}</section>`:''}<section class="panel"><h2>Run history</h2>${store.state.runs.filter(x=>x.ruleId&&rules.some(r=>r.id===x.ruleId)).slice(-30).reverse().map(x=>`<div class="category-row"><span>${esc(new Date(x.at).toLocaleString())}<small>${x.dryRun?'Dry run':esc(x.decision||'Run')} · ${esc(x.result)}</small></span>${icon(x.decision==='dismiss'?'close':'check')}</div>`).join('')||'<p>No previews or decisions recorded yet.</p>'}</section><section class="panel"><details><summary>Legacy application follow-up recipe</summary><p>Compatibility rule: when an application is marked Applied, offer one linked follow-up task seven days later. This recipe also requires a manual run and is recorded below.</p><div class="centeractions"><button class="softbutton" data-action="rule-toggle">${store.state.rules.some(x=>x.kind==='application-followup'&&x.enabled)?'Pause legacy recipe':'Enable legacy recipe'}</button><button class="softbutton" data-action="rule-preview">Preview legacy recipe</button><button class="softbutton" data-action="rule-run">Run legacy recipe</button></div><div id="rule-preview" role="status"></div></details></section>`;}
function writingPage(type){const journal=type==='journal',all=records(type),items=all.filter(x=>(journalNotebook==='all'||!journal||x.data.notebook===journalNotebook)&&(!journal||!writingQuery||`${x.title} ${x.body} ${x.data.prompt||''}`.toLocaleLowerCase().includes(writingQuery.toLocaleLowerCase()))&&(!(!journal&&diaryMonth!=='all')||x.date.startsWith(diaryMonth))).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),notebooks=['Letters to myself','Gratitude','Becoming','Boundaries','Free writing'],prompts=[['Becoming','What is changing in me that I want to honor?'],['Gratitude','What helped me feel held today?'],['Boundaries','What do I need to protect my peace this week?'],['Free writing','What is taking up the most space in my mind?']];return heading(journal?'A CONVERSATION WITH MYSELF':'THE LITTLE THINGS WERE THE BIG THINGS',journal?'Dear, <em>beautiful me.</em>':'My days, <em>remembered.</em>',journal?'Private writing with notebooks, guided starts, passage search, revisions, and readable export.':'A dated diary with month browsing, full-text search in this room, and printable memories.',type)+`<section class="panel"><div class="centeractions">${journal?`<label>Notebook<select id="journal-notebook"><option value="all">All notebooks</option>${notebooks.map(x=>`<option ${journalNotebook===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Find a passage<input id="writing-search" type="search" value="${esc(writingQuery)}" placeholder="Search my private writing"></label><button class="softbutton" data-action="journal-export">Download readable ${journalNotebook==='all'?'journal':'notebook'}</button>`:`<label>Browse month<input id="diary-month" type="month" value="${esc(diaryMonth==='all'?'':diaryMonth)}"></label><label>Find a passage<input id="writing-search" type="search" value="${esc(writingQuery)}" placeholder="Search my diary"></label><button class="softbutton" data-action="journal-export" data-kind="diary">Download my diary</button>`}<button class="textbutton" data-action="journal-print">Print this view</button></div><p class="caption">This search runs only on this private writing page. It does not add your private passages to global search.</p></section>${journal?`<section class="panel"><h2>A gentle place to begin</h2><div class="recordgrid">${prompts.map(([notebook,prompt])=>`<article class="category-row"><div><strong>${esc(notebook)}</strong><p>${esc(prompt)}</p></div><button class="softbutton" data-action="journal-prompt" data-notebook="${esc(notebook)}" data-prompt="${esc(prompt)}">Write from here ♡</button></article>`).join('')}</div></section>`:''}<section class="panel"><h2>${items.length} saved ${journal?'pages':'days'}</h2><div class="recordgrid writing-results">${items.map(x=>card(x)+`${x.data.prompt?`<p class="caption">Prompt · ${esc(x.data.prompt)}</p>`:''}`).join('')||'<p>No writing matches these filters yet.</p>'}</div></section>`}
function collectionsPage(){const collections=store.state.settings.collections||[],templates=store.state.settings.recordTemplates||[],items=active(store.state);return heading('KEEP RELATED THINGS TOGETHER','My <em>collections.</em>','Make your own shelves for pages, and save reusable starting points.')+`<section class="panel"><h2>A new collection</h2><form id="collection-create-form" class="formgrid"><label>Name<input name="name" maxlength="80" required placeholder="Moving out plans"></label><label>Description<input name="description" maxlength="500" placeholder="A shelf for things I want together"></label><fieldset class="span2"><legend>Start with pages (optional)</legend><div class="formgrid">${items.map(x=>`<label class="checklabel"><input type="checkbox" name="record" value="${esc(x.id)}">${esc(x.title)} · ${esc(types[x.type]?.name||x.type)}</label>`).join('')}</div></fieldset><button class="heart-pill">Create collection ♡</button></form></section>${collections.map(c=>`<section class="panel"><div class="panelhead"><div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p></div><button class="textbutton" data-action="collection-delete" data-id="${esc(c.id)}">Remove shelf</button></div><form class="collection-members-form" data-id="${esc(c.id)}"><div class="formgrid">${items.map(x=>`<label class="checklabel"><input type="checkbox" name="record" value="${esc(x.id)}" ${(c.recordIds||[]).includes(x.id)?'checked':''}>${esc(x.title)} · ${esc(types[x.type]?.name||x.type)}</label>`).join('')}</div><button class="softbutton">Save pages on this shelf</button></form></section>`).join('')||'<p class="calmempty">Your first collection can be as small or broad as you need.</p>'}<section class="panel"><h2>Reusable templates</h2><p>Save a record’s structure and reuse it as a starting point. Sensitive source text is never copied into a template.</p><form id="template-save-form" class="inlineform"><label>Source page<select name="source" required>${items.filter(x=>!x.sensitive).map(x=>`<option value="${esc(x.id)}">${esc(types[x.type]?.name||x.type)} · ${esc(x.title)}</option>`).join('')}</select></label><label>Template name<input name="name" maxlength="80" required placeholder="Weekly reflection"></label><button class="softbutton" ${items.some(x=>!x.sensitive)?'':'disabled'}>Save as template</button></form>${templates.map(x=>`<article class="category-row"><strong>${esc(x.name)} · ${esc(types[x.type]?.name||x.type)}</strong><button class="textbutton" data-action="template-delete" data-id="${esc(x.id)}">Remove</button></article>`).join('')||'<p class="caption">No reusable templates yet.</p>'}</section><section class="panel"><h2>Add a custom record field</h2><form id="custom-field-form" class="formgrid"><label>Field label<input name="label" maxlength="80" required placeholder="Original source"></label><label>Field type<select name="kind"><option value="text">Short text</option><option value="number">Number</option><option value="date">Date</option><option value="select">Choice list</option><option value="checkbox">Checkbox</option></select></label><label class="span2">Choices, for a choice list only<input name="options" placeholder="Foundational | Building | Fluent"></label><button class="heart-pill">Add field ♡</button></form>${(store.state.settings.customFields||[]).map(x=>`<div class="category-row"><span>${esc(x.label)} <small>${esc(x.kind)}</small></span><button class="textbutton" data-action="custom-field-delete" data-id="${esc(x.id)}">Remove</button></div>`).join('')}</section>`}
function relationshipsPage(){const graph=relationshipGraph(active(store.state),{rootId:graphRoot,maxNodes:160}),byId=new Map(graph.nodes.map(x=>[x.id,x]));return heading('THE THREADS BETWEEN MY PAGES','Connected <em>pages.</em>','Browse the links you chose. Sensitive pages are left out of this overview.')+`<section class="panel"><form id="graph-root-form" class="inlineform"><label>Start from a page<select name="root"><option value="">All connected pages</option>${graph.nodes.map(x=>`<option value="${esc(x.id)}" ${graphRoot===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><button class="softbutton">Show connections</button></form><p>${graph.nodes.length} pages · ${graph.edges.length} connections</p>${graph.nodes.map(x=>{const connected=graph.edges.filter(e=>e.from===x.id||e.to===x.id).map(e=>byId.get(e.from===x.id?e.to:e.from)).filter(Boolean);return `<article class="category-row"><div><button class="textbutton" data-action="edit" data-id="${esc(x.id)}"><strong>${esc(x.title)}</strong></button><small>${esc(types[x.type]?.name||x.type)} · ${connected.length} connected</small><small>${connected.map(y=>esc(y.title)).join(' · ')||'No saved links yet'}</small></div></article>`}).join('')||'<p>No linked public pages yet. Connect related records from their editor.</p>'}</section>`}
function duplicateReviewPanel(){const pairs=duplicateCandidates(active(store.state));return `<section class="panel"><h2>Possible duplicates</h2><p>Same type and matching title suggestions only. Sensitive entries are excluded. Review each pair before changing anything.</p>${pairs.map(p=>`<article class="category-row"><div><strong>${esc(p.keep.title)}</strong><small>${esc(types[p.keep.type]?.name||p.keep.type)} · ${esc(p.keep.date||'no date')} ↔ ${esc(p.duplicate.date||'no date')}</small><button class="textbutton" data-action="edit" data-id="${esc(p.keep.id)}">Open first</button><button class="textbutton" data-action="edit" data-id="${esc(p.duplicate.id)}">Open second</button></div><div><button class="softbutton" data-action="duplicate-keep" data-keep="${esc(p.keep.id)}" data-duplicate="${esc(p.duplicate.id)}">Keep both · reviewed</button><button class="textbutton" data-action="duplicate-merge" data-keep="${esc(p.keep.id)}" data-duplicate="${esc(p.duplicate.id)}">Merge and preserve both texts</button></div></article>`).join('')||'<p>No duplicate suggestions right now.</p>'}</section>`}
function recentPlaces(){try{const value=JSON.parse(storage.getItem('dreamhub-recent-places')||'[]');return Array.isArray(value)?value.filter(id=>routeTypes[id]).slice(0,8):[]}catch{return []}}
function rememberPlace(id){if(!routeTypes[id]||id==='search')return;try{storage.setItem('dreamhub-recent-places',JSON.stringify([id,...recentPlaces().filter(x=>x!==id)].slice(0,8)))}catch{}}
function searchPage(){const recent=recentPlaces();const found=searchRecords(active(store.state),{query:search,...searchFilters,scopeTypes:searchFilters.scope?routeTypes[searchFilters.scope]:null,includePrivateTitles:searchPrivate}),savedSearches=store.state.settings.savedSearches||[];return heading('IT’S SOMEWHERE IN MY UNIVERSE','Find a little <em>something.</em>','Search your saved records by words, type, date, and labels. Private entries stay out unless you choose to include their titles.')+`${duplicateReviewPanel()}${recent.length?`<section class="panel recent-places"><h2>Recently visited places</h2><div class="centeractions">${recent.map(id=>`<a class="softbutton" href="#${esc(id)}">${esc(routeName(id))} ↗</a>`).join('')}</div></section>`:''}<form id="global-search-form" class="panel formgrid"><label class="span2">Search my universe<input id="global-search" type="search" autofocus name="query" placeholder="A thought, a dream, a next step…" value="${esc(search)}" aria-label="Search all my records"></label><label>Search within<select name="scope"><option value="">Everywhere</option>${Object.keys(routeTypes).map(id=>`<option value="${id}" ${searchFilters.scope===id?'selected':''}>${esc(routeName(id))}</option>`).join('')}</select></label><label>Type<select name="type"><option value="">All types</option>${Object.entries(types).map(([id,t])=>`<option value="${id}" ${searchFilters.type===id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Label<input name="tag" value="${esc(searchFilters.tag||'')}" placeholder="Exact label"></label><label>From<input type="date" name="from" value="${esc(searchFilters.from||'')}"></label><label>Through<input type="date" name="to" value="${esc(searchFilters.to||'')}"></label><label class="checklabel"><input type="checkbox" name="privateTitles" ${searchPrivate?'checked':''}>Include private entry titles</label><button class="heart-pill">Search ♡</button><button type="button" class="textbutton" data-action="search-clear">Clear</button></form><form id="search-save-form" class="inlineform"><label>Name this search<input name="name" maxlength="60" required placeholder="Spring reflections"></label><button class="softbutton">Save these filters</button></form>${savedSearches.length?`<section class="panel"><h2>Saved searches</h2><div class="centeractions">${savedSearches.map(x=>`<button class="softbutton" data-action="search-apply" data-id="${esc(x.id)}">${esc(x.name)}</button><button class="textbutton" data-action="search-delete" data-id="${esc(x.id)}" aria-label="Delete saved search ${esc(x.name)}">Remove</button>`).join('')}</div></section>`:''}<p class="caption" id="search-count">${found.length} matching pages. ${searchPrivate?'Private titles included by request; private text and labels remain excluded.':'Private entries are excluded.'}</p><div class="recordgrid" id="search-results">${found.map(r=>r.sensitive?`<article class="recordcard"><span class="tiny-label">PRIVATE ${types[r.type]?.name||'entry'}</span><button class="recordtitle" data-action="edit" data-id="${esc(r.id)}"><h3>${esc(r.title)}</h3></button><p class="caption">Private text and labels concealed · ${esc(r.date)}</p></article>`:card(r)).join('')||'<p class="calmempty">No pages match these filters. Private content is not searched.</p>'}</div>`}
function inboxPage(){const tomorrow=new Date(day()+'T12:00:00');tomorrow.setDate(tomorrow.getDate()+1);const snoozeMin=day(tomorrow),rows=inboxItems(active(store.state),{state:inboxState,query:inboxQuery,today:day()});return heading('A SOFT LANDING FOR EVERY THOUGHT','My life <em>inbox.</em>','Capture first. Sort when you have room. Nothing here has to become a task.')+`<section class="panel"><form id="inbox-filter-form" class="inlineform"><label>Find in my inbox<input type="search" name="query" value="${esc(inboxQuery)}" placeholder="A word from the thought…"></label><label>Show<select name="state">${[['new','Needs sorting'],['snoozed','Snoozed'],['sorted','Sorted'],['archived','Archived']].map(([v,l])=>`<option value="${v}" ${inboxState===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="softbutton">Show entries</button></form><div class="centeractions"><button class="softbutton" data-action="inbox-bulk-state" data-state="sorted">Mark selected sorted (${inboxSelected.length})</button><button class="textbutton" data-action="inbox-bulk-state" data-state="archived">Archive selected</button></div><form id="inbox-bulk-label-form" class="inlineform"><label>Labels for selected<input name="labels" maxlength="500" placeholder="Comma separated labels"></label><label>Change<select name="mode"><option value="add">Add labels</option><option value="remove">Remove labels</option><option value="replace">Replace labels</option></select></label><button class="softbutton">Apply labels</button></form><form id="inbox-bulk-snooze-form" class="inlineform"><label>Snooze selected until<input name="until" type="date" min="${esc(snoozeMin)}" required></label><button class="softbutton">Snooze entries</button></form></section><section class="panel"><div class="recordgrid">${rows.map(r=>`<article class="recordcard"><label class="checklabel"><input type="checkbox" data-inbox-select="${esc(r.id)}" ${inboxSelected.includes(r.id)?'checked':''}>Select for sorting</label>${card(r)}<div class="centeractions"><button class="softbutton" data-action="inbox-state" data-id="${esc(r.id)}" data-state="sorted">Sorted for now</button><button class="textbutton" data-action="inbox-state" data-id="${esc(r.id)}" data-state="archived">Archive</button>${r.data.inboxUndo?`<button class="textbutton" data-action="inbox-undo" data-id="${esc(r.id)}">Undo last inbox change</button>`:''}${r.data.inboxConvertedToId?`<button class="textbutton" data-action="inbox-convert-undo" data-id="${esc(r.id)}">Undo conversion</button>`:''}</div><form class="inbox-snooze-form inlineform" data-id="${esc(r.id)}"><label>Snooze until<input name="until" type="date" min="${esc(snoozeMin)}" required></label><button class="softbutton">Snooze</button></form><form class="inbox-convert-form inlineform" data-id="${esc(r.id)}"><label>Turn into<select name="target"><option value="task">Task</option><option value="project">Project</option><option value="event">Calendar event</option><option value="transaction">Expense</option><option value="memory">Memory</option></select></label><label>Expense amount, if needed<input name="amount" inputmode="decimal" placeholder="Enter only for expense"></label><button class="softbutton">Convert</button></form></article>`).join('')||'<p class="calmempty">Your inbox is clear. Keep the space, or capture something new when it comes.</p>'}</div></section>`}
function settings(){const p=store.state.settings;return heading('MAKE YOURSELF AT HOME','My little <em>preferences.</em>','A universe that can meet you where you are.')+`<div class="settingsgrid"><section class="panel"><h2>Make it mine</h2><form id="settings-form"><label>Call me<input name="name" maxlength="50" value="${esc(p.name)}" required></label><label>My palette<select name="theme">${[['rose','Blush & lavender'],['garden','Enchanted garden'],['midnight','Midnight grimoire']].map(([v,l])=>`<option value="${v}" ${p.theme===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Dashboard mode<select name="mode">${[['dream','Dream mode'],['command','Command mode'],['gentle','A gentler day']].map(([v,l])=>`<option value="${v}" ${p.mode===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Room to breathe<select name="density"><option value="cozy" ${p.density==='cozy'?'selected':''}>Cozy</option><option value="compact" ${p.density==='compact'?'selected':''}>Compact</option></select></label><label class="checklabel"><input type="checkbox" name="motion" ${p.motion?'checked':''}> Gentle decorative motion</label><button class="heart-pill">${icon('heart')} Make it mine</button></form></section><section class="panel"><span class="tiny-label">YOUR WORDS BELONG TO YOU</span><h2>My data & little safety net</h2><p>${store.cloud?'<strong>Private cloud connected.</strong> Saved records belong to your invited account. Drafts remain on this device. Refresh to fetch other-device changes.':'<strong>Device-only review version.</strong> Entries save in this browser. Private sign-in and cloud sync aren’t connected.'} This is not end-to-end encryption or a device lock.</p><div class="data-count"><b>${active(store.state).length}</b><span>active records · ${(new Blob([JSON.stringify(store.state)]).size/1024).toFixed(1)} KB of data</span></div><div class="stackbuttons">${store.cloud?'<button class=softbutton data-action=cloud-refresh>Fetch my latest cloud pages</button><button class=softbutton data-action=sign-out>Sign out & clear local drafts</button>':''}<button class="softbutton" data-action="export">Export my full backup (JSON)</button><button class="softbutton" data-action="export-encrypted">Export encrypted full backup</button><button class="softbutton" data-action="export-csv">Export my money journal (CSV)</button><button class="softbutton" data-action="export-writing">Export my writing (Markdown)</button><button class="softbutton" data-action="import">Review a backup to import</button><a href="#trash" class="softbutton">Visit the recovery room ↗</a></div><p class="caption">Encrypted backups use a separate passphrase that DreamHub cannot recover. Full restore replaces the whole saved workspace after explicit confirmation. Other imports preview and merge by ID; conflicts stop the import. Deleted records stay recoverable until you explicitly erase them.</p></section><section class="panel"><h2>My rooms, my choice</h2><p>Hide a room without deleting its records. Restore it here anytime.</p><div class="roomtoggles">${groups.flatMap(x=>x[1]).filter(x=>!['home','settings'].includes(x[0])).map(([id,title])=>`<label class="checklabel"><input type="checkbox" data-room="${id}" ${p.hidden.includes(id)?'':'checked'}>${title}</label>`).join('')}</div></section><section class="panel"><h2>Import history & provenance</h2>${(store.state.settings.importHistory||[]).slice().reverse().map(x=>`<article class="category-row"><div><strong>${esc(x.sourceLabel)} · ${esc(x.importedAt.slice(0,10))}</strong><small>${x.addedRecordIds.length} added · ${x.identicalRecordIds.length} already present · ${x.keptConflictIds.length} current versions kept</small><small>Backup dated ${esc(x.backupCreatedAt||'not recorded')}</small></div></article>`).join('')||'<p>No backups have been merged into this workspace yet.</p>'}</section><section class="panel"><h2>What’s working & what’s next</h2><p>This build includes connected records, draft recovery, trash, exact-cent budgets, mixed feelings, a 78-card reference, local spread draws, planner, focus history, trackers, and manually run follow-up rules.</p><p><strong>Still to connect:</strong> managed authentication, private cloud data and two-device sync. Photo cards stay local. Browser-based workflows have no guaranteed background delivery.</p><p>Rich text, advanced recurrence, drag-and-resize dashboards, attachment vaults, and the full v5 automation engine remain later release work.</p><p class="caption">No paid integrations, AI calls, subscriptions, or bank connections have been enabled.</p></section></div>`}
function trashPage(){const rs=store.state.records.filter(x=>x.deletedAt);return heading('NOT EVERY GOODBYE HAS TO BE FOREVER','The little <em>recovery room.</em>','Restore a page, or permanently erase one after reviewing it.')+`<div class="recordgrid">${rs.map(r=>`<article class="recordcard"><span class="tiny-label">${types[r.type]?.name||r.type} · ${esc(r.deletedAt.slice(0,10))}</span><h3>${esc(r.title)}</h3><div class="cardactions"><button class="softbutton" data-action="restore" data-id="${r.id}">Bring it back ♡</button><button class="textbutton" data-action="purge" data-id="${r.id}">Erase permanently</button></div></article>`).join('')||'<p class="calmempty">Nothing here needs rescuing. ♡</p>'}</div>`}
function conciergePage(){const overview=lifeOverview({records:store.state.records.filter(r=>r.deletedAt===null),date:day()});const suggestions=conciergeSuggestions(overview);const recurrenceRules=store.state.records.filter(r=>r.type==='scheduleDecision'&&!r.deletedAt&&r.data?.frequency&&r.data?.start).map(r=>({id:r.id,title:r.title,start:r.data.start,frequency:r.data.frequency,interval:Number(r.data.interval)||1,enabled:r.status!=='Paused'}));let recurring=[];try{recurring=recurringProposals(recurrenceRules,{from:day(),to:day()});}catch(e){recurring=[{title:'Review recurrence settings',date:day(),status:'invalid',proposalId:'invalid'}];}recurring=recurrenceInbox(recurring,active(store.state));return heading('YOUR LIFE, BEAUTIFULLY CONNECTED','Life Concierge','Recommendations only — nothing is booked, purchased or sent without your approval.','task')+`<section class="panel"><h2>Today's proposed rhythm</h2><p>${overview.agenda.blocks.length} time blocks · ${overview.agenda.deferred.length} deferred · ${overview.agenda.conflicts.length} scheduling conflicts.</p><div class="recordlist">${overview.agenda.blocks.map(b=>`<article class="recordcard"><strong>${esc(b.title)}</strong><p>${String(Math.floor(b.from/60)).padStart(2,'0')}:${String(b.from%60).padStart(2,'0')} — suggested, not scheduled</p></article>`).join('')||'<p>No uncommitted tasks to propose today.</p>'}</div></section><section class="panel"><h2>Gentle recommendations</h2>${suggestions.map(x=>`<article class="recordcard"><strong>${esc(x.title)}</strong><p>${esc(x.reason)}</p><small>Awaiting your decision — no automatic action</small></article>`).join('')||'<p>Nothing urgent to suggest right now.</p>'}</section><section class="panel"><h2>Recurring proposals awaiting approval</h2>${recurring.map(p=>`<article class="recordcard"><strong>${esc(p.title)}</strong><p>${esc(p.date)} · Awaiting your decision</p><div class="cardactions"><button class="softbutton" data-action="recurrence-approve" data-proposal="${esc(p.proposalId)}">Approve ♡</button><button class="softbutton" data-action="recurrence-reject" data-proposal="${esc(p.proposalId)}">Dismiss</button></div></article>`).join('')||'<p>No recurring proposals due today.</p>'}</section><section class="panel"><h2>My connected worlds</h2><p>Studio: ${overview.studio.qualified.length} qualified leads · ${overview.studio.followups.length} follow-up drafts due</p><p>Belle Academy: ${overview.academy.items.length} saved learning entries · ${overview.academy.weeklyHours} curriculum hours per week</p><p>Social & culture: ${overview.social.today.length} saved experiences today</p><p>Spending: no bank balances are assumed; enter verified received cash before making spending decisions.</p></section>`;}
function heartPanel(){return heading('THE UNIVERSAL HEART','Capture a little <em>something.</em>','A fast capture from anywhere. Sort it now or leave it in your inbox.')+`<section class="panel"><h2>What is on my mind? ♡</h2><form id="heart-form" class="formgrid"><label>What kind of thing?<select name="type">${actionTypes.map(t=>`<option value="${t}">${esc(types[t]?.name||t)}</option>`).join('')}</select></label><label>Give it a name<input name="title" required maxlength="240" placeholder="A little thought, a big possibility…"></label><label>Date (optional)<input name="date" type="date"></label><label>Labels<input name="tags" maxlength="500" placeholder="Optional, comma separated"></label><label class="span2">A few more words<textarea name="body" maxlength="10000" placeholder="Capture the thought; details can wait."></textarea></label><label class="checklabel span2"><input type="checkbox" name="sensitive"> Keep this entry out of search</label><button class="heart-pill" type="submit">Save to my inbox ♡</button></form><p class="caption">Saved locally. No email, purchase, booking, or other external action is triggered.</p></section>`;}
function render(){try{const focused=document.activeElement?.id;let content=route==='heart'?heartPanel():route==='home'?home():route==='concierge'?conciergePage():route==='focus'?focus():route==='calendar'?calendar():route==='movement'?movementGarden():route==='estate'?estate():route==='rules'?rulePage():route==='settings'?settings():route==='trash'?trashPage():route==='search'?searchPage():routeTypes[route]?modulePage():home();shell(content);if(focused==='global-search')$('#global-search')?.focus();}catch(e){error('This page couldn’t load. Your saved data is still retained. '+e.message)}}
const formValue=(name,value,type='text',options=null)=>`<label>${esc(name)}${options?`<select name="${esc(type)}">${options.map(o=>`<option ${String(value)===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${esc(name)}">${esc(value)}</textarea>`:''}</label>`;
function fieldHtml(key,label,kind,value='',opts=[]){if(kind==='checkbox')return `<label class=checklabel><input type=checkbox name="data.${key}" ${value?'checked':''}>${esc(label)}</label>`;if(kind==='select')return `<label>${esc(label)}<select name="data.${key}">${opts.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;if(kind==='textarea')return `<label class="span2">${esc(label)}<textarea name="data.${key}" rows="3">${esc(value)}</textarea></label>`;return `<label>${esc(label)}<input name="data.${key}" type="${kind==='money'?'text':kind==='integer'?'number':kind}" ${kind==='money'?'inputmode="decimal"':kind==='integer'?'min="1" max="1000" step="1"':kind==='number'?'min="0" max="100" step=".01"':''} value="${esc(value)}"></label>`;}
function getDraft(id){try{return JSON.parse(storage.getItem(draftPrefix+id)||'null')}catch{return null}}
function customFieldHtml(r){const fields=store.state.settings.customFields||[],values=r.data.customFields||{};return fields.length?`<section class="panel custom-fields"><h3>My custom details</h3><div class="formgrid">${fields.map(f=>f.kind==='checkbox'?`<label class="checklabel"><input type="checkbox" name="custom.${esc(f.id)}" ${values[f.id]?'checked':''}>${esc(f.label)}</label>`:f.kind==='select'?`<label>${esc(f.label)}<select name="custom.${esc(f.id)}"><option value="">Choose…</option>${f.options.map(o=>`<option value="${esc(o)}" ${values[f.id]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`:`<label>${esc(f.label)}<input name="custom.${esc(f.id)}" type="${f.kind==='number'?'number':f.kind==='date'?'date':'text'}" value="${esc(values[f.id]??'')}"></label>`).join('')}</div></section>`:'';}
function openEditor(type='note',id=null,preset={}){if($('#editor').open&&!saveDraft())return;if(!types[type])type='note';const existing=id?store.state.records.find(r=>r.id===id):null;editBase=existing?structuredClone(existing):null;writingType=existing?.type||type;formId=existing?.id||preset.id||'new-'+writingType;const draft=getDraft(formId);if(draft&&editBase)editBase.version=draft.baseVersion;const r=draft?.record||existing||record(writingType,{...preset,data:{...preset.data}});if(writingType==='task'&&!existing&&!draft){r.date=preset.date||'';r.data.dueMode=preset.data?.dueMode||(preset.date?'on':'someday');r.data.dependsOn=preset.data?.dependsOn||[];}if(!existing&&!draft)editBase=structuredClone(r);photo=r.data.photo||'';const def=types[writingType],privateType=['journal','diary','mood','dream','reading','ritual','careLog','petCare','account','plannedIncome','envelope','fund','fundContribution','transaction','bill','debt','saving','property','homeItem','homeAdmin','homeChecklist','client','proposal','invoice','studioPayment','studioChange','studioMilestone','deliverable','studioOutreach','launchQA','careerQuestion','careerAsset','careerContact','careerSource'].includes(writingType);if(!existing&&!draft&&privateType)r.sensitive=true;$('#editor').innerHTML=`<form id="record-form" data-id="${r.id}" data-type="${writingType}"><div class="editorhead"><div><span class="tiny-label">A LITTLE ROOM FOR ${esc(def.plural)}</span><h2 id="editor-title">${existing?'My':'A fresh'} <em>${def.name.toLowerCase()}.</em></h2></div><button type="button" class="iconbutton" data-action="close-editor" aria-label="Save draft and close">${icon('close')}</button></div><div class="editorbody"><div class="draft-status" id="draft-status">${draft?'Recovered your unsaved draft.':existing?'Your saved page. Edits become a draft until you save.':'A new little beginning. Drafts stay on this device.'}</div>${existing?.sourceProvenance?`<p class="caption import-origin">Imported from ${esc(existing.sourceProvenance.sourceLabel)} on ${esc(existing.sourceProvenance.importedAt.slice(0,10))} · source record ${esc(existing.sourceProvenance.sourceRecordId)}</p>`:''}${!existing&&(store.state.settings.recordTemplates||[]).some(x=>x.type===writingType)?`<div class="inlineform template-picker"><label>Start with a template<select id="template-choice"><option value="">Choose a saved template…</option>${store.state.settings.recordTemplates.filter(x=>x.type===writingType).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><button type="button" class="softbutton" data-action="template-apply">Apply template</button></div>`:''}<label class="titlefield"><span>Give it a name</span><input name="title" placeholder="A little thought, a big possibility…" value="${esc(r.title==='Untitled'?'':r.title)}" maxlength="240" required></label><div class="formgrid"><label>Date<input type="date" name="date" value="${esc(r.date)}"></label><label>Status<select name="status">${['Now','Next','Later','Done','Applied','Interview','Offer','Closed','Active','Paused','Someday'].map(x=>`<option ${r.status===x?'selected':''}>${x}</option>`).join('')}</select></label></div>${writingType==='mood'?`<fieldset class="moodfieldset"><legend>What’s here? Choose the whole mix.</legend><div class="moodselect">${moods.map(m=>{const f=r.data.feelings?.find(x=>x.name===m);return `<label><input type="checkbox" name="feeling" aria-label="Feeling ${m}" value="${m}" ${f?'checked':''}><span>${m}</span><select name="intensity.${m}" aria-label="Intensity for ${m}">${[1,2,3,4,5].map(i=>`<option value="${i}" ${i===(f?.intensity||3)?'selected':''}>${i}/5</option>`).join('')}</select></label>`}).join('')}</div><label>Other feelings (comma separated)<input name="customFeelings" value="${esc((r.data.feelings||[]).filter(f=>!moods.includes(f.name)).map(f=>f.name).join(', '))}" placeholder="Mixy, wistful, quietly proud…"></label></fieldset>`:''}<label>My words<textarea name="body" class="writingarea" placeholder="Whatever you need to put down. It doesn’t have to be perfect.">${esc(r.body)}</textarea></label><div class="formgrid">${def.fields.map(([key,label,kind,opts])=>fieldHtml(key,label,kind,['positions','items'].includes(key)&&Array.isArray(r.data[key])?r.data[key].join('\n'):kind==='money'&&Number.isSafeInteger(r.data[key])?(r.data[key]/100).toFixed(2):r.data[key]??(key==='target'?1:kind==='select'?opts[0]:''),opts)).join('')}${writingType==='task'?`<label class="span2">Wait for these tasks first<select name="dependsOn" multiple size="4">${records('task').filter(x=>x.id!==r.id&&x.data.parentTaskId!==r.id).map(x=>`<option value="${esc(x.id)}" ${(r.data.dependsOn||[]).includes(x.id)?'selected':''}>${esc(x.title)} · ${esc(x.status)}</option>`).join('')}</select><small>A task stays blocked until every selected prerequisite is complete.</small></label>`:''}${customFieldHtml(r)}<label>Energy<select name="energy">${['Low','Medium','High'].map(x=>`<option ${r.energy===x?'selected':''}>${x}</option>`).join('')}</select></label>${['task','project'].includes(writingType)?`<label>Time I want to give it (minutes)<input name="minutes" type="number" min="1" max="1440" value="${r.minutes||15}"></label>`:''}<label class="span2">Little labels (comma separated)<input name="tags" value="${esc(r.tags.join(', '))}" placeholder="Career, home, a new chapter…"></label><label class="span2">Connect this to another page<select name="links" multiple size="3">${active(store.state).filter(x=>x.id!==r.id).map(x=>`<option value="${x.id}" ${r.links.includes(x.id)?'selected':''}>${esc(x.title)} · ${types[x.type]?.name||x.type}</option>`).join('')}</select><small>Optional. Select one or more related pages.</small></label>${['memory','wish','beauty','wardrobe','travel','experience','season'].includes(writingType)?`<label class="span2">A little picture (optional)<input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp"><small>Compressed and saved in your local record. Large libraries need cloud storage.</small></label>${photo?'<p class="caption">A picture is attached. <button type="button" class="textbutton" data-action="remove-photo">Remove picture</button></p>':''}`:''}</div><label class="checklabel"><input type="checkbox" name="sensitive" ${r.sensitive||(!existing&&privateType)?'checked':''}> Conceal this entry’s text in global search previews</label>${existing?`<div class=linked-pages><span class=tiny-label>CONNECTED PAGES</span>${active(store.state).filter(x=>r.links.includes(x.id)||x.links.includes(r.id)).map(x=>`<button type=button class=softbutton data-action=edit data-id="${x.id}">${esc(x.title)} ↗</button>`).join('')||'<p class=caption>Link a goal, task, reflection, or other page above.</p>'}</div>${existing.history?.length?`<details class=revision-history><summary>My earlier versions (${existing.history.length})</summary>${existing.history.slice().reverse().map(x=>`<article><h3>Version ${esc(x.version)} · ${esc(x.title)}</h3><p>${esc(x.body||'No body text.')}</p></article>`).join('')}</details>`:''}<p class="caption">Created ${new Date(existing.createdAt).toLocaleString()} · saved version ${existing.version}</p>`:''}<div id="form-error" class="formerror" role="alert"></div></div><div class="editorfoot"><button type="button" class="textbutton" data-action="discard-draft">Discard draft</button><button class="heart-pill" type="submit">${icon('heart')} Save my little page</button></div></form>`;const sensitivityControl=$('#record-form [name=sensitive]');if(sensitivityControl)sensitivityControl.checked=Boolean(r.sensitive||(!existing&&privateType));if(!$('#editor').open)$('#editor').showModal();if(draft?.raw){for(const [key,value] of Object.entries(draft.raw)){const el=$('#record-form').querySelector('[name="'+CSS.escape(key)+'"]');if(el&&el.type!=='checkbox'&&!el.hasAttribute('multiple')&&key!=='feeling'){if(el.localName==='select'){for(const opt of el.querySelectorAll('option')){if((opt.getAttribute('value')??opt.textContent)===value)opt.setAttribute('selected','');else opt.removeAttribute('selected');}}else el.value=value;}}}$('#record-form input[name=title]').focus();}
function readForm(validateForm=true){const form=$('#record-form'),f=new FormData(form),type=form.dataset.type,previous=editBase||getDraft(formId)?.record||record(type,{id:form.dataset.id});const r={...previous,id:form.dataset.id,type,title:String(f.get('title')||'').trim(),body:String(f.get('body')||''),date:String(f.get('date')||''),status:String(f.get('status')||'Next'),energy:String(f.get('energy')||'Medium'),minutes:Number(f.get('minutes')||15),tags:String(f.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),links:f.getAll('links'),sensitive:f.has('sensitive'),data:{...previous.data,photo}};r.data.customFields={...(previous.data.customFields||{})};for(const field of store.state.settings.customFields||[]){const raw=f.get('custom.'+field.id);r.data.customFields[field.id]=field.kind==='checkbox'?f.has('custom.'+field.id):field.kind==='number'?(raw===''?null:Number(raw)):String(raw||'');}for(const [key,label,kind]of types[type].fields){const raw=f.get('data.'+key);if(kind==='checkbox'){r.data[key]=f.has('data.'+key);continue;}if(kind==='money'){if(raw){try{r.data[key]=moneyToMinor(raw)}catch(e){if(validateForm)throw e;r.data[key]=previous.data[key]||0;}}else r.data[key]=0;}else if(['number','integer'].includes(kind))r.data[key]=Number(raw)||0;else r.data[key]=String(raw||'');}if(type==='event'&&!r.data.timeZone)delete r.data.timeZone;if(type==='task'){r.data.dependsOn=f.getAll('dependsOn');const mode=r.data.dueMode||'someday';if(mode==='someday'){r.date='';r.data.dueEnd='';}else if(mode==='on'||mode==='before'){r.data.dueEnd='';}taskDueWindow(r);r.data.dependsOn=validateTaskDependencies(r.id,r.data.dependsOn,active(store.state));}if(type==='habit'){r.data.logs=previous.data.logs||[];if(!r.data.target)r.data.target=1;}if(type==='mood'){r.data.feelings=f.getAll('feeling').map(name=>({name,intensity:Number(f.get('intensity.'+name))||3}));String(f.get('customFeelings')||'').split(',').map(x=>x.trim()).filter(Boolean).forEach(name=>{if(!r.data.feelings.some(x=>x.name===name))r.data.feelings.push({name,intensity:3});});}if(validateForm&&!r.title)throw Error('Give this page a little name before saving.');return r;}
function saveDraft(){try{const r=readForm(false);storage.setItem(draftPrefix+formId,JSON.stringify({record:r,baseVersion:editBase?.version||null,at:now(),raw:Object.fromEntries(new FormData($('#record-form')).entries())}));$('#draft-status').textContent='Draft kept on this device · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});return true;}catch(e){error('Your draft could not be saved. Keep this editor open and copy your writing before leaving. '+e.message);return false}}
function download(content,name,mime='text/plain'){const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
